function overlapsRock(rocks, x, y, r) {
  for (const rock of rocks) {
    const dx = x - rock.x;
    const dy = y - rock.y;
    if (dx * dx + dy * dy < (rock.r + r) * (rock.r + r)) return true;
  }
  return false;
}

function nearProtected(protectedPoints, x, y, pad = 0) {
  for (const p of protectedPoints) {
    const dx = x - p.x;
    const dy = y - p.y;
    if (dx * dx + dy * dy < (p.r + pad) * (p.r + pad)) return true;
  }
  return false;
}

export function createWorld(seed = 20261031) {
  const rng = mulberry32(seed);
  const rocks = [];
  const decorations = [];
  const nodes = [];
  const chests = [];
  const vents = [];
  const schools = [];
  const landmarks = [];

  const protectedPoints = [
    { x: WORLD.baseX, y: 240, r: 460 },
    ...RELIC_DEFS.map((r) => ({ x: r.x, y: r.y, r: 330 })),
    ...VENT_DEFS.map((v) => ({ x: v.x, y: v.y, r: 220 })),
  ];

  // ── Rock formations, ledges and arches ──────────────────────────────
  const counts = [19, 22, 25, 23, 21];
  ZONES.forEach((zone, zi) => {
    const count = counts[zi];
    for (let i = 0; i < count; i++) {
      let placed = false;
      for (let attempt = 0; attempt < 18 && !placed; attempt++) {
        const x = 130 + rng() * (WORLD.width - 260);
        const y = zone.y0 + 170 + rng() * Math.max(160, zone.y1 - zone.y0 - 340);
        const baseR = 58 + rng() * (zi > 2 ? 120 : 95);
        if (nearProtected(protectedPoints, x, y, baseR + 90)) continue;
        if (overlapsRock(rocks, x, y, baseR + 60)) continue;
        const pieces = 1 + Math.floor(rng() * 3);
        const cluster = [];
        for (let p = 0; p < pieces; p++) {
          const angle = rng() * Math.PI * 2;
          const off = p === 0 ? 0 : 20 + rng() * baseR * 0.85;
          const r = p === 0 ? baseR : baseR * (0.55 + rng() * 0.42);
          const rx = x + Math.cos(angle) * off;
          const ry = y + Math.sin(angle) * off * 0.62;
          cluster.push({ x: rx, y: ry, r });
        }
        const kind = rng() < 0.18 ? 'moss' : rng() < 0.1 ? 'dark' : 'rock';
        const seedVal = Math.floor(rng() * 100000);
        for (const c of cluster) {
          rocks.push({ ...c, kind, seed: seedVal, zone: zone.id, zi });
        }
        placed = true;
      }
    }
  });

  // Guaranteed shelves beneath landmarks.
  const shelves = [
    { x: WRECK.x - 80, y: WRECK.y + 210, r: 185, kind: 'shelf', zone: 'shallows' },
    { x: WRECK.x + 150, y: WRECK.y + 245, r: 140, kind: 'shelf', zone: 'shallows' },
    { x: RUIN_SITES[0].x, y: RUIN_SITES[0].y + 230, r: 280, kind: 'shelf', zone: 'abyss' },
    { x: RUIN_SITES[1].x, y: RUIN_SITES[1].y + 210, r: 240, kind: 'shelf', zone: 'abyss' },
    { x: BONES.x, y: BONES.y + 150, r: 210, kind: 'shelf', zone: 'twilight' },
  ];
  shelves.forEach((s) => rocks.push({ ...s, seed: 991, zi: ZONES.findIndex((z) => z.id === s.zone) }));

  // ── Vents ───────────────────────────────────────────────────────────
  VENT_DEFS.forEach((v, i) => {
    vents.push({ ...v, id: `vent-${i}`, r: v.type === 'thermal' ? 150 : 170, phase: rng() * 10 });
    // a small rocky mouth for each vent
    rocks.push({ x: v.x, y: v.y + 120, r: 48 + rng() * 26, kind: 'vent', zone: v.zone, seed: 300 + i, zi: ZONES.findIndex((z) => z.id === v.zone) });
  });

  // ── Ruins ───────────────────────────────────────────────────────────
  const ruins = RUIN_SITES.map((site, idx) => {
    const columns = [];
    const count = 5 + Math.floor(rng() * 3);
    for (let i = 0; i < count; i++) {
      const cx = site.x + (i - count / 2) * 92 * site.scale + (rng() - 0.5) * 30;
      const h = (130 + rng() * 210) * site.scale;
      columns.push({ x: cx, y: site.y + 40, h, w: 34 + rng() * 20, broken: rng() > 0.45, seed: rng() * 1000 });
      rocks.push({ x: cx, y: site.y + 60, r: 24 + rng() * 12, kind: 'ruin', zone: 'abyss', seed: 700 + i, zi: 3 });
    }
    return { ...site, columns, id: `ruin-${idx}` };
  });

  // ── Wreck ───────────────────────────────────────────────────────────
  rocks.push(
    { x: WRECK.x - 150, y: WRECK.y + 80, r: 80, kind: 'wreck', zone: 'shallows', seed: 121, zi: 0 },
    { x: WRECK.x + 60, y: WRECK.y + 90, r: 100, kind: 'wreck', zone: 'shallows', seed: 122, zi: 0 },
    { x: WRECK.x + 230, y: WRECK.y + 120, r: 64, kind: 'wreck', zone: 'shallows', seed: 123, zi: 0 },
  );

  // ── Coral, kelp, anemones and glowing flora ─────────────────────────
  const coralRocks = rocks.filter((r) => r.r > 55 && (r.zone === 'shallows' || r.zone === 'kelp'));
  const deepRocks = rocks.filter((r) => r.r > 55 && (r.zone === 'twilight' || r.zone === 'abyss' || r.zone === 'rift'));
  for (let i = 0; i < 72; i++) {
    const rock = coralRocks[Math.floor(rng() * coralRocks.length)];
    if (!rock) continue;
    decorations.push({
      type: rng() < 0.46 ? 'coral' : rng() < 0.7 ? 'fan' : 'anemone',
      x: rock.x + (rng() - 0.5) * rock.r * 1.2,
      y: rock.y - rock.r * (0.55 + rng() * 0.2),
      scale: 0.55 + rng() * 1.15,
      phase: rng() * Math.PI * 2,
      seed: Math.floor(rng() * 9999),
      hue: rng(),
      zone: rock.zone,
    });
  }
  const kelpRocks = rocks.filter((r) => r.zone === 'kelp' && r.r > 70);
  for (let i = 0; i < 95; i++) {
    const rock = kelpRocks[Math.floor(rng() * kelpRocks.length)];
    if (!rock) continue;
    decorations.push({
      type: 'kelp',
      x: rock.x + (rng() - 0.5) * rock.r * 1.5,
      y: rock.y - rock.r * 0.5,
      height: 180 + rng() * 440,
      scale: 0.7 + rng() * 0.8,
      phase: rng() * Math.PI * 2,
      seed: Math.floor(rng() * 9999),
      hue: rng(),
      zone: 'kelp',
    });
  }
  for (let i = 0; i < 58; i++) {
    const rock = deepRocks[Math.floor(rng() * deepRocks.length)];
    if (!rock) continue;
    decorations.push({
      type: rng() < 0.55 ? 'glowplant' : rng() < 0.8 ? 'tube' : 'anemone',
      x: rock.x + (rng() - 0.5) * rock.r * 1.3,
      y: rock.y - rock.r * (0.45 + rng() * 0.3),
      height: 40 + rng() * 130,
      scale: 0.6 + rng() * 1.1,
      phase: rng() * Math.PI * 2,
      seed: Math.floor(rng() * 9999),
      hue: rng(),
      zone: rock.zone,
    });
  }

  // ── Collectible nodes ───────────────────────────────────────────────
  const nodeCounts = [23, 25, 24, 22, 19];
  let nodeId = 0;
  ZONES.forEach((zone, zi) => {
    const weights = [
      [['scrap', 56], ['pearl', 32], ['crystal', 5], ['repair', 7]],
      [['scrap', 39], ['pearl', 43], ['crystal', 12], ['repair', 6]],
      [['scrap', 22], ['pearl', 30], ['crystal', 42], ['repair', 6]],
      [['scrap', 14], ['pearl', 21], ['crystal', 59], ['repair', 6]],
      [['scrap', 23], ['pearl', 17], ['crystal', 54], ['repair', 6]],
    ][zi];
    for (let i = 0; i < nodeCounts[zi]; i++) {
      let placed = false;
      for (let attempt = 0; attempt < 70 && !placed; attempt++) {
        const x = 160 + rng() * (WORLD.width - 320);
        const y = zone.y0 + 120 + rng() * Math.max(120, zone.y1 - zone.y0 - 220);
        if (nearProtected([{ x: WORLD.baseX, y: 250, r: 260 }], x, y)) continue;
        if (overlapsRock(rocks, x, y, 54)) continue;
        if (nodes.some((n) => (n.x - x) ** 2 + (n.y - y) ** 2 < 150 * 150)) continue;
        const type = weightedPick(rng, weights);
        const amount = type === 'repair' ? 1 : type === 'crystal' ? 1 + Math.floor(rng() * 3) : 1 + Math.floor(rng() * 3);
        nodes.push({ id: `node-${nodeId++}`, type, x, y, amount, phase: rng() * 10, seed: rng() * 999, zone: zone.id });
        placed = true;
      }
    }
  });

  // ── Chests ──────────────────────────────────────────────────────────
  const chestDefs = SPECIAL_CHESTS.map((c) => ({ ...c, special: true }));
  const chestZoneCounts = [2, 3, 2, 3, 2];
  ZONES.forEach((zone, zi) => {
    for (let i = 0; i < chestZoneCounts[zi]; i++) {
      for (let attempt = 0; attempt < 60; attempt++) {
        const x = 170 + rng() * (WORLD.width - 340);
        const y = zone.y0 + 160 + rng() * Math.max(120, zone.y1 - zone.y0 - 300);
        if (nearProtected([{ x: WORLD.baseX, y: 250, r: 300 }], x, y)) continue;
        if (overlapsRock(rocks, x, y, 60)) continue;
        if (chests.some((c) => (c.x - x) ** 2 + (c.y - y) ** 2 < 220 * 220)) continue;
        chestDefs.push({ x, y, zone: zone.id, special: false });
        break;
      }
    }
  });

  const chestLoot = {
    shallows: { scrap: [5, 9], pearl: [1, 3], crystal: [0, 1] },
    kelp: { scrap: [4, 8], pearl: [2, 4], crystal: [0, 2] },
    twilight: { scrap: [3, 6], pearl: [2, 4], crystal: [2, 4] },
    abyss: { scrap: [2, 5], pearl: [1, 3], crystal: [3, 6] },
    rift: { scrap: [4, 8], pearl: [2, 4], crystal: [4, 7] },
  };
  chestDefs.forEach((def, i) => {
    const loot = chestLoot[def.zone];
    const roll = (range) => Math.floor(range[0] + rng() * (range[1] - range[0] + 1));
    chests.push({
      id: `chest-${i}`,
      x: def.x,
      y: def.y,
      zone: def.zone,
      label: def.label || null,
      special: !!def.special,
      loot: { scrap: roll(loot.scrap), pearl: roll(loot.pearl), crystal: roll(loot.crystal) },
      phase: rng() * 10,
    });
  });

  // ── Relics and the leviathan pearl ──────────────────────────────────
  const relics = RELIC_DEFS.map((r) => ({ ...r, phase: rng() * 10 }));
  const leviathanPearl = { id: 'leviathan-pearl', x: 7660, y: 9380, phase: rng() * 10 };

  // ── Ambient fish schools ────────────────────────────────────────────
  const schoolZones = ['shallows', 'shallows', 'shallows', 'kelp', 'kelp', 'kelp', 'kelp', 'twilight', 'twilight', 'twilight', 'twilight', 'shallows'];
  schoolZones.forEach((zid, i) => {
    const z = ZONE_BY_ID[zid];
    schools.push({
      id: `school-${i}`,
      x: 300 + rng() * (WORLD.width - 600),
      y: z.y0 + 200 + rng() * (z.y1 - z.y0 - 400),
      zone: zid,
      count: 5 + Math.floor(rng() * 10),
      dir: rng() < 0.5 ? -1 : 1,
      speed: 20 + rng() * 34,
      spread: 40 + rng() * 80,
      phase: rng() * 10,
      type: zid === 'twilight' ? 'lantern' : rng() < 0.3 ? 'gold' : 'silver',
    });
  });

  // ── Map landmarks ───────────────────────────────────────────────────
  landmarks.push({ type: 'base', x: WORLD.baseX, y: 150, label: 'The Aurora' });
  landmarks.push({ type: 'wreck', x: WRECK.x, y: WRECK.y, label: 'The Calypso' });
  landmarks.push({ type: 'bones', x: BONES.x, y: BONES.y, label: 'Whale fall' });
  RUIN_SITES.forEach((r) => landmarks.push({ type: 'ruin', x: r.x, y: r.y, label: 'Sunken ruins' }));
  landmarks.push({ type: 'pearl', x: leviathanPearl.x, y: leviathanPearl.y, label: 'Leviathan Pearl' });

  return {
    seed,
    rocks,
    decorations,
    nodes,
    chests,
    vents,
    schools,
    relics,
    ruins,
    wreck: WRECK,
    bones: BONES,
    leviathanPearl,
    landmarks,
    seabedY,
  };
}

export function upgradeCost(upgrade, level) {
  if (level >= upgrade.max) return null;
  return upgrade.cost(level);
}

export function pressureRating(upgrades) {
  return upgrades.hull || 0;
}

const KEY = 'deep-ocean-expedition-v1';

export function defaultSave() {
  return {
    version: 1,
    started: false,
    completed: false,
    resources: { scrap: 0, pearl: 0, crystal: 0 },
    upgrades: { oxygen: 0, thruster: 0, hull: 0, lamp: 0, sonar: 0, pulse: 0 },
    relics: [],
    leviathanPearl: false,
    collectedNodes: [],
    openedChests: [],
    discoveredZones: ['shallows'],
    player: { x: 1250, y: 280, oxygen: 100, hull: 100 },
    stats: {
      maxDepth: 0,
      dives: 0,
      time: 0,
      deaths: 0,
      chests: 0,
      nodes: 0,
      scrap: 0,
      pearl: 0,
      crystal: 0,
    },
    muted: false,
    savedAt: 0,
  };
}

function merge(base, incoming) {
  if (!incoming || typeof incoming !== 'object') return base;
  const out = { ...base };
  for (const key of Object.keys(base)) {
    const b = base[key];
    const i = incoming[key];
    if (i === undefined || i === null) continue;
    if (Array.isArray(b)) out[key] = Array.isArray(i) ? i : b;
    else if (typeof b === 'object') out[key] = merge(b, i);
    else if (typeof i === typeof b) out[key] = i;
  }
  return out;
}

export function loadSave() {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || parsed.version !== 1) return null;
    return merge(defaultSave(), parsed);
  } catch {
    return null;
  }
}

export function writeSave(data) {
  try {
    data.savedAt = Date.now();
    localStorage.setItem(KEY, JSON.stringify(data));
    return true;
  } catch {
    return false;
  }
}

export function clearSave() {
  try {
    localStorage.removeItem(KEY);
  } catch {
    /* storage can be unavailable in private mode */
  }
}

export class OceanAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.ambient = null;
    this.muted = false;
    this.ready = false;
    this.bubbleTimer = 0;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.7;
    this.master.connect(this.ctx.destination);
    this.buildAmbient();
    this.ready = true;
  }

  buildAmbient() {
    const ctx = this.ctx;
    const now = ctx.currentTime;

    // Deep filtered noise bed.
    const length = ctx.sampleRate * 4;
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.985 + white * 0.015;
      data[i] = last * 2.8;
    }
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    noise.loop = true;
    const noiseFilter = ctx.createBiquadFilter();
    noiseFilter.type = 'lowpass';
    noiseFilter.frequency.value = 420;
    noiseFilter.Q.value = 0.6;
    const noiseGain = ctx.createGain();
    noiseGain.gain.value = 0.055;
    noise.connect(noiseFilter).connect(noiseGain).connect(this.master);
    noise.start();

    // Slow pressure drone.
    const droneGain = ctx.createGain();
    droneGain.gain.value = 0.026;
    droneGain.connect(this.master);
    [55, 82.4, 110.2].forEach((freq, i) => {
      const osc = ctx.createOscillator();
      osc.type = i === 2 ? 'triangle' : 'sine';
      osc.frequency.value = freq;
      const g = ctx.createGain();
      g.gain.value = i === 2 ? 0.22 : 0.55;
      osc.connect(g).connect(droneGain);
      osc.start();
      const lfo = ctx.createOscillator();
      lfo.frequency.value = 0.045 + i * 0.017;
      const lfoGain = ctx.createGain();
      lfoGain.gain.value = 0.35;
      lfo.connect(lfoGain).connect(g.gain);
      lfo.start();
    });

    // Distant water movement.
    const swell = ctx.createOscillator();
    swell.frequency.value = 0.07;
    const swellGain = ctx.createGain();
    swellGain.gain.value = 0.018;
    swell.connect(swellGain).connect(noiseGain.gain);
    swell.start();

    this.ambient = { noise, noiseGain, droneGain };
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(muted ? 0 : 0.7, this.ctx.currentTime + 0.25);
    }
  }

  tone(freq, duration, type = 'sine', volume = 0.1, slide = 0, delay = 0) {
    if (!this.ready || this.muted) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t0 + duration);
    gain.gain.setValueAtTime(0, t0);
    gain.gain.linearRampToValueAtTime(volume, t0 + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    osc.connect(gain).connect(this.master);
    osc.start(t0);
    osc.stop(t0 + duration + 0.02);
  }

  noiseBurst(duration = 0.2, volume = 0.08, cutoff = 700) {
    if (!this.ready || this.muted) return;
    const ctx = this.ctx;
    const length = Math.floor(ctx.sampleRate * duration);
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) {
      data[i] = (Math.random() * 2 - 1) * (1 - i / length) ** 2;
    }
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = cutoff;
    const gain = ctx.createGain();
    gain.gain.value = volume;
    src.connect(filter).connect(gain).connect(this.master);
    src.start();
  }

  collect(type) {
    if (type === 'crystal') {
      this.tone(740, 0.25, 'sine', 0.07, 240);
      this.tone(1180, 0.3, 'sine', 0.035, 160, 0.05);
    } else if (type === 'pearl') {
      this.tone(620, 0.22, 'triangle', 0.07, 180);
      this.tone(930, 0.26, 'sine', 0.035, 120, 0.04);
    } else if (type === 'repair') {
      this.tone(420, 0.14, 'square', 0.04, 180);
      this.tone(640, 0.24, 'sine', 0.05, 120, 0.08);
    } else {
      this.tone(520, 0.12, 'triangle', 0.055, 90);
      this.tone(780, 0.16, 'sine', 0.03, 60, 0.03);
    }
  }

  chest() {
    [392, 523, 659, 784].forEach((f, i) => this.tone(f, 0.55, 'sine', 0.055, 0, i * 0.09));
    this.noiseBurst(0.5, 0.03, 1200);
  }

  relic() {
    [261.6, 392, 523, 659, 784, 1046].forEach((f, i) => this.tone(f, 1.3, 'sine', 0.045, 0, i * 0.11));
    this.tone(65, 2.2, 'sine', 0.06, 15);
  }

  damage() {
    this.noiseBurst(0.32, 0.16, 320);
    this.tone(70, 0.4, 'sine', 0.13, -24);
  }

  pulse() {
    this.tone(220, 0.55, 'sine', 0.1, 420);
    this.tone(440, 0.4, 'triangle', 0.045, 220, 0.03);
    this.noiseBurst(0.25, 0.04, 1500);
  }

  bubble() {
    this.tone(300 + Math.random() * 500, 0.1, 'sine', 0.018, 260);
  }

  upgrade() {
    [330, 440, 554, 660].forEach((f, i) => this.tone(f, 0.5, 'triangle', 0.055, 0, i * 0.08));
  }

  zone() {
    this.tone(196, 1.8, 'sine', 0.045, 12);
    this.tone(294, 1.4, 'sine', 0.025, 8, 0.2);
  }

  victory() {
    [261.6, 329.6, 392, 523, 659, 784].forEach((f, i) => this.tone(f, 2.4, 'sine', 0.05, 0, i * 0.14));
    this.tone(65, 3, 'sine', 0.07, 12);
  }

  death() {
    this.tone(120, 1.4, 'sine', 0.12, -60);
    this.noiseBurst(1.2, 0.1, 260);
  }

  sonar() {
    this.tone(880, 0.7, 'sine', 0.05, -620);
    this.tone(1320, 0.4, 'sine', 0.02, -800, 0.04);
  }
}

import {
  clamp, damp, dist, angleLerp, rand, mulberry32, lerp,
} from './utils.js';
import { ZONE_BY_ID, ZONES, WORLD, seabedY } from './world.js';

export class Player {
  constructor() {
    this.x = WORLD.baseX;
    this.y = 280;
    this.vx = 0;
    this.vy = 0;
    this.radius = 22;
    this.angle = Math.PI / 2;
    this.oxygen = 100;
    this.maxOxygen = 100;
    this.hull = 100;
    this.maxHull = 100;
    this.boosting = false;
    this.invuln = 0;
    this.hitFlash = 0;
    this.bubbleTimer = 0;
    this.thrusterLevel = 0;
    this.lampLevel = 0;
    this.hullLevel = 0;
    this.bob = 0;
    this.dead = false;
    this.surfaceGlow = 0;
    this.ambient = 0;
  }

  applyUpgrades(upgrades) {
    const oldMaxO = this.maxOxygen;
    const oldMaxH = this.maxHull;
    this.maxOxygen = 100 + (upgrades.oxygen || 0) * 25;
    this.maxHull = 100 + (upgrades.hull || 0) * 25;
    this.thrusterLevel = upgrades.thruster || 0;
    this.lampLevel = upgrades.lamp || 0;
    this.hullLevel = upgrades.hull || 0;
    if (this.maxOxygen > oldMaxO) this.oxygen = Math.min(this.maxOxygen, this.oxygen + (this.maxOxygen - oldMaxO));
    if (this.maxHull > oldMaxH) this.hull = Math.min(this.maxHull, this.hull + (this.maxHull - oldMaxH));
    this.oxygen = Math.min(this.oxygen, this.maxOxygen);
    this.hull = Math.min(this.hull, this.maxHull);
  }

  placeAt(x, y, oxygen = this.maxOxygen, hull = this.maxHull) {
    this.x = x;
    this.y = y;
    this.vx = 0;
    this.vy = 0;
    this.oxygen = clamp(oxygen, 0, this.maxOxygen);
    this.hull = clamp(hull, 0, this.maxHull);
    this.dead = false;
    this.invuln = 1.5;
    this.hitFlash = 0;
  }

  update(dt, input, world, game) {
    this.invuln = Math.max(0, this.invuln - dt);
    this.hitFlash = Math.max(0, this.hitFlash - dt);
    this.bob += dt;

    let ax = input.x;
    let ay = input.y;
    const mag = Math.hypot(ax, ay);
    if (mag > 1) {
      ax /= mag;
      ay /= mag;
    }
    const moving = mag > 0.06;
    this.boosting = moving && input.boost && this.oxygen > 0;
    const speedBonus = 1 + this.thrusterLevel * 0.1;
    const accel = 1420 * speedBonus * (this.boosting ? 1.34 : 1);
    const maxSpeed = 325 * speedBonus * (this.boosting ? 1.48 : 1);

    if (moving) {
      this.vx += ax * accel * dt;
      this.vy += ay * accel * dt;
    }

    // Water resistance.
    const drag = Math.exp(-(this.boosting ? 1.65 : 2.45) * dt);
    this.vx *= drag;
    this.vy *= drag;

    // A little neutral buoyancy so stopping feels like water.
    this.vy -= 2.2 * dt;

    const sp = Math.hypot(this.vx, this.vy);
    if (sp > maxSpeed) {
      this.vx = (this.vx / sp) * maxSpeed;
      this.vy = (this.vy / sp) * maxSpeed;
    }

    this.x += this.vx * dt;
    this.y += this.vy * dt;

    // World and seabed boundaries.
    this.x = clamp(this.x, 70, WORLD.width - 70);
    const floor = seabedY(this.x) - this.radius - 8;
    this.y = clamp(this.y, 36, floor);

    // Collide with rock bodies.
    for (const rock of world.rocks) {
      const dx = this.x - rock.x;
      const dy = this.y - rock.y;
      const rr = rock.r + this.radius;
      const d2 = dx * dx + dy * dy;
      if (d2 < rr * rr && d2 > 0.0001) {
        const d = Math.sqrt(d2);
        const nx = dx / d;
        const ny = dy / d;
        this.x = rock.x + nx * rr;
        this.y = rock.y + ny * rr;
        const vn = this.vx * nx + this.vy * ny;
        if (vn < 0) {
          this.vx -= vn * nx * 1.25;
          this.vy -= vn * ny * 1.25;
        }
      }
    }

    // Facing follows movement, with a gentle tilt.
    const targetAngle = sp > 22 ? Math.atan2(this.vy, this.vx) : this.angle;
    this.angle = angleLerp(this.angle, targetAngle, 1 - Math.exp(-7 * dt));

    // Thruster bubbles.
    this.bubbleTimer -= dt;
    if (moving && this.bubbleTimer <= 0) {
      this.bubbleTimer = this.boosting ? 0.035 : 0.075;
      const back = this.angle + Math.PI;
      game.particles.bubble(
        this.x + Math.cos(back) * 30 + rand(-5, 5),
        this.y + Math.sin(back) * 30 + rand(-5, 5),
        { size: rand(2, 5), rise: rand(30, 85), drift: rand(-12, 12), life: rand(1.2, 2.8) },
      );
    }
  }
}

function findOpenPosition(world, zone, rng, radius = 40) {
  for (let i = 0; i < 90; i++) {
    const x = 140 + rng() * (WORLD.width - 280);
    const y = zone.y0 + 180 + rng() * Math.max(120, zone.y1 - zone.y0 - 360);
    let blocked = false;
    for (const rock of world.rocks) {
      const dx = x - rock.x;
      const dy = y - rock.y;
      if (dx * dx + dy * dy < (rock.r + radius + 30) ** 2) {
        blocked = true;
        break;
      }
    }
    if (!blocked) return { x, y };
  }
  return { x: 400 + rng() * (WORLD.width - 800), y: zone.y0 + (zone.y1 - zone.y0) * 0.5 };
}

function baseCreature(type, x, y, extra = {}) {
  return {
    type,
    x, y,
    homeX: x,
    homeY: y,
    vx: 0,
    vy: 0,
    angle: 0,
    dir: Math.random() < 0.5 ? -1 : 1,
    phase: Math.random() * Math.PI * 2,
    state: 'patrol',
    stateT: 0,
    attackCd: 0,
    stun: 0,
    size: 30,
    damage: 0,
    speed: 60,
    detect: 0,
    aggro: 0,
    ...extra,
  };
}

export function createCreatures(world, seed = 7741) {
  const rng = mulberry32(seed);
  const creatures = [];
  const zone = (id) => ZONE_BY_ID[id];

  const spawn = (type, zoneId, extra, radius = 45) => {
    const p = findOpenPosition(world, zone(zoneId), rng, radius);
    creatures.push(baseCreature(type, p.x, p.y, { zone: zoneId, ...extra }));
  };

  for (let i = 0; i < 3; i++) {
    spawn('shark', 'kelp', {
      size: 42, damage: 14, speed: 155, detect: 500, dir: rng() < 0.5 ? -1 : 1,
      patrolSpeed: 55, phase: rng() * 10,
    }, 70);
  }
  for (let i = 0; i < 3; i++) {
    spawn('shark', 'twilight', {
      size: 46, damage: 16, speed: 170, detect: 560, dir: rng() < 0.5 ? -1 : 1,
      patrolSpeed: 60, phase: rng() * 10,
    }, 70);
  }

  for (let i = 0; i < 7; i++) {
    spawn('jelly', 'twilight', {
      size: 26 + rng() * 10, damage: 8, speed: 18, detect: 0,
      tentacle: 60 + rng() * 50, glow: rng() < 0.4 ? 'violet' : 'cyan',
      phase: rng() * 10,
    }, 50);
  }
  for (let i = 0; i < 7; i++) {
    spawn('jelly', 'abyss', {
      size: 30 + rng() * 14, damage: 10, speed: 20, detect: 0,
      tentacle: 70 + rng() * 70, glow: rng() < 0.5 ? 'violet' : 'amber',
      phase: rng() * 10,
    }, 50);
  }

  for (let i = 0; i < 3; i++) {
    spawn('angler', 'abyss', {
      size: 38, damage: 20, speed: 74, detect: 440, dir: rng() < 0.5 ? -1 : 1,
      phase: rng() * 10,
    }, 60);
  }
  for (let i = 0; i < 2; i++) {
    spawn('angler', 'rift', {
      size: 42, damage: 22, speed: 82, detect: 470, dir: rng() < 0.5 ? -1 : 1,
      phase: rng() * 10,
    }, 60);
  }

  for (let i = 0; i < 3; i++) {
    spawn('eel', 'abyss', {
      size: 28, damage: 13, speed: 260, detect: 320, dir: rng() < 0.5 ? -1 : 1,
      phase: rng() * 10,
    }, 50);
  }
  for (let i = 0; i < 3; i++) {
    spawn('eel', 'rift', {
      size: 30, damage: 15, speed: 280, detect: 340, dir: rng() < 0.5 ? -1 : 1,
      phase: rng() * 10,
    }, 50);
  }

  // Urchins sit on coral and rock ledges.
  const urchinRocks = world.rocks.filter((r) => r.r > 60 && (r.zone === 'shallows' || r.zone === 'kelp'));
  for (let i = 0; i < 14; i++) {
    const rock = urchinRocks[Math.floor(rng() * urchinRocks.length)];
    if (!rock) continue;
    const angle = rng() * Math.PI * 2;
    const x = rock.x + Math.cos(angle) * rock.r * 0.82;
    const y = rock.y + Math.sin(angle) * rock.r * 0.82;
    creatures.push(baseCreature('urchin', x, y, {
      zone: rock.zone, size: 16 + rng() * 7, damage: 8, speed: 0, detect: 0,
      phase: rng() * 10, homeX: x, homeY: y,
    }));
  }

  // Stingrays are harmless ambience.
  for (let i = 0; i < 8; i++) {
    const zid = i < 4 ? 'shallows' : 'kelp';
    spawn('ray', zid, {
      size: 40 + rng() * 20, damage: 0, speed: 52, detect: 180,
      dir: rng() < 0.5 ? -1 : 1, phase: rng() * 10, patrolSpeed: 46,
    }, 80);
  }

  // The abyssal guardian circles the third relic.
  const relic = world.relics[2];
  if (relic) {
    creatures.push(baseCreature('guardian', relic.x - 260, relic.y + 80, {
      zone: 'abyss', size: 68, damage: 24, speed: 108, detect: 620,
      dir: 1, phase: 2.4, guardian: true,
    }));
  }

  return creatures;
}

function steer(c, tx, ty, speed, dt, responsiveness = 3.2) {
  const dx = tx - c.x;
  const dy = ty - c.y;
  const d = Math.hypot(dx, dy) || 1;
  const desiredX = (dx / d) * speed;
  const desiredY = (dy / d) * speed;
  c.vx = damp(c.vx, desiredX, responsiveness, dt);
  c.vy = damp(c.vy, desiredY, responsiveness, dt);
}

function wander(c, dt, speed) {
  c.phase += dt * 0.32;
  const tx = c.homeX + Math.sin(c.phase * 0.7) * 180;
  const ty = c.homeY + Math.cos(c.phase * 0.53) * 110;
  steer(c, tx, ty, speed, dt, 1.2);
}

export function updateCreatures(creatures, player, dt, game) {
  const px = player.x;
  const py = player.y;
  for (const c of creatures) {
    c.attackCd = Math.max(0, c.attackCd - dt);
    c.stateT += dt;
    c.phase += dt;

    if (c.stun > 0) {
      c.stun -= dt;
      c.x += c.vx * dt;
      c.y += c.vy * dt;
      c.vx *= Math.exp(-1.4 * dt);
      c.vy *= Math.exp(-1.4 * dt);
      continue;
    }

    const dx = px - c.x;
    const dy = py - c.y;
    const d = Math.hypot(dx, dy);

    switch (c.type) {
      case 'shark': {
        if (c.state === 'patrol' && d < c.detect) {
          c.state = 'chase';
          c.stateT = 0;
          c.aggro = 1;
        }
        if (c.state === 'chase') {
          steer(c, px, py, c.speed, dt, 3.4);
          if (d < c.size + player.radius + 12 && c.attackCd <= 0) {
            game.damage(c.damage, 'shark');
            c.attackCd = 1.9;
            c.state = 'retreat';
            c.stateT = 0;
          } else if (d > c.detect * 1.6) {
            c.state = 'patrol';
            c.stateT = 0;
          }
        } else if (c.state === 'retreat') {
          steer(c, c.x - dx * 2, c.y - dy * 2, c.speed * 1.25, dt, 3);
          if (c.stateT > 2.6) {
            c.state = 'patrol';
            c.stateT = 0;
          }
        } else {
          wander(c, dt, c.patrolSpeed);
        }
        c.dir = c.vx >= 0 ? 1 : -1;
        c.angle = Math.atan2(c.vy, c.vx);
        break;
      }
      case 'jelly': {
        // Slow, eerie drift with a vertical pulse.
        const pulse = Math.sin(c.phase * 1.15);
        c.vx = damp(c.vx, Math.sin(c.phase * 0.27) * c.speed * 0.6, 1.1, dt);
        c.vy = damp(c.vy, -12 - pulse * 20, 1.3, dt);
        c.x += c.vx * dt;
        c.y += c.vy * dt;
        if (c.y < c.homeY - 220) c.vy += 12 * dt;
        if (c.y > c.homeY + 220) c.vy -= 12 * dt;
        c.dir = c.vx >= 0 ? 1 : -1;
        break;
      }
      case 'angler': {
        if (d < c.detect) {
          if (d > 130) steer(c, px, py, c.speed, dt, 1.8);
          else {
            steer(c, px, py, c.speed * 1.9, dt, 4);
            if (d < c.size + player.radius + 8 && c.attackCd <= 0) {
              game.damage(c.damage, 'anglerfish');
              c.attackCd = 2.2;
              c.state = 'retreat';
              c.stateT = 0;
            }
          }
        } else if (c.state === 'retreat') {
          steer(c, c.x - dx, c.y - dy, c.speed, dt, 2);
          if (c.stateT > 2.4) c.state = 'patrol';
        } else {
          wander(c, dt, c.speed * 0.42);
        }
        c.dir = c.vx >= 0 ? 1 : -1;
        c.angle = Math.atan2(c.vy, c.vx);
        break;
      }
      case 'guardian': {
        if (d < c.detect) {
          if (d > 210) steer(c, px, py, c.speed, dt, 1.4);
          else {
            steer(c, px, py, c.speed * 1.7, dt, 3);
            if (d < c.size + player.radius + 10 && c.attackCd <= 0) {
              game.damage(c.damage, 'the guardian');
              c.attackCd = 2.8;
              c.stateT = 0;
            }
          }
        } else {
          wander(c, dt, c.speed * 0.3);
        }
        c.dir = c.vx >= 0 ? 1 : -1;
        c.angle = Math.atan2(c.vy, c.vx);
        break;
      }
      case 'eel': {
        if (c.state === 'lunge') {
          steer(c, px, py, c.speed, dt, 6);
          if (d < c.size + player.radius + 8 && c.attackCd <= 0) {
            game.damage(c.damage, 'eel');
            c.attackCd = 2;
            c.state = 'retreat';
            c.stateT = 0;
          } else if (c.stateT > 1.15) {
            c.state = 'retreat';
            c.stateT = 0;
          }
        } else if (c.state === 'retreat') {
          steer(c, c.x - dx, c.y - dy, c.speed * 0.9, dt, 4);
          if (c.stateT > 2.2) {
            c.state = 'patrol';
            c.stateT = 0;
            c.homeX = c.x;
            c.homeY = c.y;
          }
        } else {
          c.phase += dt * 1.4;
          c.vx = damp(c.vx, Math.sin(c.phase) * 22, 1.5, dt);
          c.vy = damp(c.vy, Math.cos(c.phase * 0.7) * 16, 1.5, dt);
          c.x += c.vx * dt;
          c.y += c.vy * dt;
          if (d < c.detect) {
            c.state = 'lunge';
            c.stateT = 0;
          }
        }
        c.dir = c.vx >= 0 ? 1 : -1;
        c.angle = Math.atan2(c.vy, c.vx);
        break;
      }
      case 'ray': {
        c.phase += dt * 0.7;
        const fleeing = d < c.detect;
        const speed = fleeing ? c.speed * 1.8 : c.patrolSpeed;
        c.vx = damp(c.vx, c.dir * speed, 1.1, dt);
        c.vy = damp(c.vy, Math.sin(c.phase) * 18, 1.4, dt);
        c.x += c.vx * dt;
        c.y += c.vy * dt;
        if (c.x < 120) c.dir = 1;
        if (c.x > WORLD.width - 120) c.dir = -1;
        if (fleeing) c.dir = dx >= 0 ? 1 : -1;
        c.angle = Math.sin(c.phase) * 0.15;
        break;
      }
      case 'urchin': {
        c.phase += dt;
        break;
      }
      default:
        break;
    }

    // Keep creatures in open water and out of the seabed.
    c.x = clamp(c.x, 80, WORLD.width - 80);
    c.y = clamp(c.y, 80, seabedY(c.x) - c.size - 10);

    // Contact damage.
    if (c.damage > 0 && c.type !== 'urchin' && c.attackCd <= 0) {
      if (dist(c.x, c.y, px, py) < c.size + player.radius - 4) {
        game.damage(c.damage, c.type === 'guardian' ? 'the guardian' : c.type);
        c.attackCd = c.type === 'jelly' ? 2.2 : 1.8;
        if (c.type === 'shark') {
          c.state = 'retreat';
          c.stateT = 0;
        }
      }
    } else if (c.type === 'urchin' && c.attackCd <= 0) {
      if (dist(c.x, c.y, px, py) < c.size + player.radius + 2) {
        game.damage(c.damage, 'sea urchin');
        c.attackCd = 2.4;
      }
    }
  }
}

export function repelCreatures(creatures, x, y, radius, player) {
  for (const c of creatures) {
    const dx = c.x - x;
    const dy = c.y - y;
    const d = Math.hypot(dx, dy);
    if (d < radius && c.type !== 'urchin') {
      const nx = d > 0.001 ? dx / d : 1;
      const ny = d > 0.001 ? dy / d : 0;
      const force = (1 - d / radius) * 620;
      c.vx += nx * force;
      c.vy += ny * force;
      c.stun = c.guardian ? 2.2 : 3.1;
      c.attackCd = 1.5;
      if (c.type === 'shark') c.state = 'retreat';
      if (c.type === 'eel') c.state = 'retreat';
    }
  }
}

// ═══════════════════ PARTICLES ═══════════════════
export class Particles {
  constructor() {
    this.items = [];
    this.max = 620;
  }

  add(p) {
    if (this.items.length >= this.max) this.items.shift();
    this.items.push(p);
  }

  bubble(x, y, opts = {}) {
    this.add({
      kind: 'bubble',
      x, y,
      vx: opts.drift ?? rand(-10, 10),
      vy: -(opts.rise ?? rand(24, 60)),
      size: opts.size ?? rand(1.8, 4.6),
      life: opts.life ?? rand(1.5, 3.4),
      maxLife: opts.life ?? rand(1.5, 3.4),
      wobble: rand(0, 10),
      alpha: opts.alpha ?? 0.8,
    });
  }

  spark(x, y, color = '#8ff8ff', opts = {}) {
    const angle = opts.angle ?? rand(0, Math.PI * 2);
    const speed = opts.speed ?? rand(30, 150);
    this.add({
      kind: 'spark',
      x, y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      size: opts.size ?? rand(1.2, 3.2),
      life: opts.life ?? rand(0.4, 1.2),
      maxLife: opts.life ?? 1.2,
      color,
      drag: opts.drag ?? 2.6,
    });
  }

  burst(x, y, color = '#8ff8ff', count = 12, power = 120) {
    for (let i = 0; i < count; i++) {
      this.spark(x, y, color, { angle: rand(0, Math.PI * 2), speed: rand(power * 0.3, power), size: rand(1.3, 3.6) });
    }
  }

  damage(x, y) {
    for (let i = 0; i < 10; i++) {
      this.spark(x, y, i % 2 ? '#ff8b7a' : '#ffd0a0', { angle: rand(0, Math.PI * 2), speed: rand(50, 230), size: rand(1.5, 4), life: rand(0.25, 0.7) });
    }
    this.bubble(x, y, { size: rand(3, 7), rise: rand(50, 120), life: rand(0.8, 1.8) });
  }

  update(dt) {
    const items = this.items;
    for (let i = items.length - 1; i >= 0; i--) {
      const p = items[i];
      p.life -= dt;
      if (p.life <= 0) {
        items.splice(i, 1);
        continue;
      }
      if (p.kind === 'bubble') {
        p.wobble += dt * 4.2;
        p.x += (p.vx + Math.sin(p.wobble) * 12) * dt;
        p.y += p.vy * dt;
        p.vy *= Math.exp(-0.12 * dt);
        p.vx *= Math.exp(-0.5 * dt);
      } else {
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.vx *= Math.exp(-(p.drag || 2) * dt);
        p.vy *= Math.exp(-(p.drag || 2) * dt);
        p.vy += 12 * dt;
      }
    }
  }
}

