export function drawLandmarks(r, game) {
  drawWreck(r, game);
  drawRuins(r, game);
  drawBones(r, game);
  drawLeviathanPearl(r, game);
}

function drawWreck(r, game) {
  const w = game.world.wreck;
  if (!visible(r, w.x, w.y, 320)) return;
  const { ctx } = r;
  ctx.save();
  ctx.translate(w.x, w.y);
  ctx.rotate(w.angle);
  ctx.scale(w.scale, w.scale);

  // Silt.
  ctx.fillStyle = 'rgba(4, 24, 30, 0.55)';
  ctx.beginPath();
  ctx.ellipse(0, 96, 230, 44, 0, 0, Math.PI * 2);
  ctx.fill();

  // Broken hull.
  const hull = ctx.createLinearGradient(0, -80, 0, 90);
  hull.addColorStop(0, '#4a3d34');
  hull.addColorStop(0.35, '#2f2b27');
  hull.addColorStop(1, '#151c1d');
  ctx.fillStyle = hull;
  ctx.beginPath();
  ctx.moveTo(-190, 12);
  ctx.quadraticCurveTo(-174, -58, -88, -68);
  ctx.lineTo(100, -60);
  ctx.quadraticCurveTo(186, -46, 196, 20);
  ctx.quadraticCurveTo(160, 84, 62, 90);
  ctx.lineTo(-92, 86);
  ctx.quadraticCurveTo(-186, 74, -190, 12);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(131, 169, 160, 0.25)';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Torn opening.
  ctx.fillStyle = '#050b0d';
  ctx.beginPath();
  ctx.moveTo(-46, -62);
  ctx.quadraticCurveTo(18, -84, 88, -56);
  ctx.lineTo(72, 18);
  ctx.quadraticCurveTo(14, 40, -38, 18);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(132, 100, 70, 0.45)';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Ribs.
  ctx.strokeStyle = 'rgba(106, 84, 66, 0.7)';
  ctx.lineWidth = 3;
  for (let i = 0; i < 6; i++) {
    const x = -130 + i * 38;
    ctx.beginPath();
    ctx.moveTo(x, -64 + Math.abs(i - 2) * 2);
    ctx.quadraticCurveTo(x + 8, 0, x - 4, 78);
    ctx.stroke();
  }

  // Deck rail.
  ctx.strokeStyle = 'rgba(74, 110, 104, 0.5)';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(-150, -50);
  ctx.lineTo(-70, -58);
  ctx.stroke();

  // Portholes.
  for (let i = 0; i < 4; i++) {
    const x = -126 + i * 62;
    ctx.fillStyle = 'rgba(8, 26, 29, 0.9)';
    ctx.beginPath();
    ctx.arc(x, -8, 9, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = 'rgba(119, 159, 149, 0.4)';
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.fillStyle = 'rgba(255, 203, 130, 0.09)';
    ctx.beginPath();
    ctx.arc(x, -8, 6, 0, Math.PI * 2);
    ctx.fill();
  }

  // Broken mast.
  ctx.save();
  ctx.translate(-84, -58);
  ctx.rotate(-0.72);
  ctx.fillStyle = '#3b2c24';
  ctx.fillRect(-5, -110, 10, 118);
  ctx.strokeStyle = 'rgba(135, 105, 79, 0.4)';
  ctx.lineWidth = 1;
  ctx.strokeRect(-5, -110, 10, 118);
  ctx.restore();

  // Seaweed on the hull.
  ctx.strokeStyle = 'rgba(50, 130, 95, 0.55)';
  ctx.lineWidth = 2;
  for (let i = 0; i < 5; i++) {
    const x = -150 + i * 67;
    ctx.beginPath();
    ctx.moveTo(x, 80);
    ctx.quadraticCurveTo(x + 14, 46, x + 4, 14);
    ctx.stroke();
  }

  // Name plate.
  ctx.save();
  ctx.rotate(0.01);
  ctx.font = '11px "Bebas Neue", sans-serif';
  ctx.fillStyle = 'rgba(190, 160, 115, 0.55)';
  ctx.textAlign = 'center';
  ctx.fillText('C A L Y P S O', 112, 54);
  ctx.restore();
  ctx.restore();
}

function drawRuins(r, game) {
  const { ctx } = r;
  for (const site of game.world.ruins) {
    if (!visible(r, site.x, site.y, 380)) continue;
    // Ambient glow behind the ruins.
    const aura = ctx.createRadialGradient(site.x, site.y - 60, 20, site.x, site.y - 60, 340);
    aura.addColorStop(0, 'rgba(90, 220, 255, 0.055)');
    aura.addColorStop(1, 'rgba(90, 220, 255, 0)');
    ctx.fillStyle = aura;
    ctx.fillRect(site.x - 340, site.y - 400, 680, 560);

    for (let ci = 0; ci < site.columns.length; ci++) {
      const c = site.columns[ci];
      const col = ctx.createLinearGradient(c.x - c.w / 2, 0, c.x + c.w / 2, 0);
      col.addColorStop(0, '#0a1a2a');
      col.addColorStop(0.45, '#173a50');
      col.addColorStop(1, '#07111f');
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.moveTo(c.x - c.w / 2, c.y);
      ctx.lineTo(c.x - c.w / 2, c.y - c.h + (c.broken ? 16 : 0));
      if (c.broken) {
        ctx.lineTo(c.x - c.w * 0.16, c.y - c.h - 8);
        ctx.lineTo(c.x + c.w * 0.12, c.y - c.h + 10);
      }
      ctx.lineTo(c.x + c.w / 2, c.y - c.h + (c.broken ? 20 : 0));
      ctx.lineTo(c.x + c.w / 2, c.y);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = 'rgba(116, 204, 216, 0.16)';
      ctx.lineWidth = 1.2;
      ctx.stroke();

      // Capital.
      if (!c.broken) {
        ctx.fillStyle = '#1c4355';
        ctx.fillRect(c.x - c.w * 0.72, c.y - c.h - 8, c.w * 1.44, 9);
        ctx.strokeStyle = 'rgba(120, 220, 230, 0.16)';
        ctx.strokeRect(c.x - c.w * 0.72, c.y - c.h - 8, c.w * 1.44, 9);
      }

      // Glowing runes.
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      for (let g = 0; g < 3; g++) {
        const gy = c.y - 34 - g * 46;
        if (gy < c.y - c.h + 12) break;
        const a = 0.22 + Math.sin(r.time * 1.4 + ci * 2 + g) * 0.12;
        ctx.fillStyle = `rgba(94, 235, 255, ${a})`;
        ctx.fillRect(c.x - 3, gy, 6, 2);
        ctx.fillRect(c.x - 1.5, gy + 4, 3, 5);
      }
      ctx.restore();
    }

    // Fallen blocks.
    ctx.fillStyle = 'rgba(10, 27, 42, 0.9)';
    for (let i = 0; i < 5; i++) {
      const bx = site.x - 200 + i * 97;
      const by = site.y + 28 + (i % 2) * 14;
      ctx.save();
      ctx.translate(bx, by);
      ctx.rotate((i % 3 - 1) * 0.14);
      ctx.fillRect(-16, -9, 32, 18);
      ctx.strokeStyle = 'rgba(100, 180, 200, 0.12)';
      ctx.strokeRect(-16, -9, 32, 18);
      ctx.restore();
    }
  }
}

function drawBones(r, game) {
  const b = game.world.bones;
  if (!visible(r, b.x, b.y, 340)) return;
  const { ctx } = r;
  ctx.save();
  ctx.translate(b.x, b.y);
  ctx.rotate(b.angle);
  ctx.scale(b.scale, b.scale);
  const bone = 'rgba(190, 212, 200, 0.46)';
  const boneDark = 'rgba(98, 129, 121, 0.38)';

  // Skull.
  ctx.fillStyle = bone;
  ctx.beginPath();
  ctx.ellipse(132, -12, 55, 27, -0.12, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(172, -20);
  ctx.lineTo(228, -5);
  ctx.lineTo(170, 14);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(4, 18, 22, 0.65)';
  ctx.beginPath();
  ctx.arc(146, -14, 7, 0, Math.PI * 2);
  ctx.fill();

  // Spine.
  ctx.strokeStyle = bone;
  ctx.lineWidth = 8;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-178, 0);
  ctx.quadraticCurveTo(-20, -24, 108, -8);
  ctx.stroke();

  // Ribs.
  ctx.strokeStyle = boneDark;
  ctx.lineWidth = 5;
  for (let i = 0; i < 9; i++) {
    const x = -150 + i * 31;
    const y = -4 + Math.sin(i * 0.4) * 8;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.quadraticCurveTo(x - 8, y - 62 - i * 2, x + 16, y - 96);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.quadraticCurveTo(x + 4, y + 54, x - 12, y + 82);
    ctx.stroke();
  }

  // Moss.
  ctx.strokeStyle = 'rgba(74, 162, 94, 0.28)';
  ctx.lineWidth = 2;
  for (let i = 0; i < 4; i++) {
    const x = -100 + i * 56;
    ctx.beginPath();
    ctx.moveTo(x, -20);
    ctx.quadraticCurveTo(x + 12, -48, x + 2, -72);
    ctx.stroke();
  }
  ctx.restore();
}

function drawLeviathanPearl(r, game) {
  if (game.save.leviathanPearl) return;
  const p = game.world.leviathanPearl;
  if (!visible(r, p.x, p.y, 360)) return;
  const { ctx } = r;
  const bob = Math.sin(r.time * 1.1 + p.phase) * 8;
  ctx.save();
  ctx.translate(p.x, p.y + bob);
  ctx.globalCompositeOperation = 'lighter';
  const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, 210);
  glow.addColorStop(0, 'rgba(255, 236, 188, 0.38)');
  glow.addColorStop(0.3, 'rgba(255, 198, 120, 0.16)');
  glow.addColorStop(1, 'rgba(255, 170, 90, 0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(0, 0, 210, 0, Math.PI * 2);
  ctx.fill();

  // Rings.
  ctx.strokeStyle = 'rgba(255, 218, 160, 0.35)';
  ctx.lineWidth = 1.4;
  for (let i = 0; i < 3; i++) {
    const rr = 78 + i * 26 + Math.sin(r.time * 0.9 + i) * 5;
    ctx.beginPath();
    ctx.ellipse(0, 0, rr, rr * 0.34, r.time * 0.08 + i * 0.5, 0, Math.PI * 2);
    ctx.stroke();
  }

  const orb = ctx.createRadialGradient(-18, -20, 4, 0, 0, 72);
  orb.addColorStop(0, '#fffdf0');
  orb.addColorStop(0.35, '#ffe8b8');
  orb.addColorStop(0.75, '#d9a45c');
  orb.addColorStop(1, '#6a3d1d');
  ctx.fillStyle = orb;
  ctx.beginPath();
  ctx.arc(0, 0, 66, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';
  ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
  ctx.beginPath();
  ctx.ellipse(-22, -24, 15, 8, -0.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

export function drawVents(r, game) {
  const { ctx, time } = r;
  for (const vent of game.world.vents) {
    if (!visible(r, vent.x, vent.y, 320)) continue;
    const thermal = vent.type === 'thermal';
    const color = thermal ? '#ff8a4d' : '#7df0cf';
    const height = thermal ? 420 : 520;
    const bob = Math.sin(time * 0.8 + vent.phase) * 4;

    ctx.save();
    ctx.translate(vent.x, vent.y + bob);

    // Glow column.
    ctx.globalCompositeOperation = 'lighter';
    const col = ctx.createLinearGradient(0, 60, 0, -height);
    col.addColorStop(0, rgba(color, thermal ? 0.2 : 0.15));
    col.addColorStop(0.3, rgba(color, thermal ? 0.1 : 0.07));
    col.addColorStop(1, rgba(color, 0));
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.moveTo(-46, 70);
    ctx.quadraticCurveTo(-60, -height * 0.55, -26, -height);
    ctx.lineTo(30, -height);
    ctx.quadraticCurveTo(66, -height * 0.5, 46, 70);
    ctx.closePath();
    ctx.fill();

    // Mouth light.
    const mouth = ctx.createRadialGradient(0, 20, 0, 0, 20, 80);
    mouth.addColorStop(0, rgba(color, 0.3));
    mouth.addColorStop(1, rgba(color, 0));
    ctx.fillStyle = mouth;
    ctx.beginPath();
    ctx.arc(0, 20, 80, 0, Math.PI * 2);
    ctx.fill();

    // Bubbles.
    for (let i = 0; i < 14; i++) {
      const speed = thermal ? 56 : 44;
      const t = ((time * speed + i * 47 + vent.phase * 30) % height);
      const y = 20 - t;
      const x = Math.sin(t * 0.022 + i * 1.7 + time * 0.4) * (12 + i * 1.6);
      const size = 1.5 + (i % 4) * 1.2;
      ctx.fillStyle = rgba(thermal ? '#ffd2a2' : '#d6fffa', 0.26 + (1 - t / height) * 0.35);
      ctx.beginPath();
      ctx.arc(x, y, size, 0, Math.PI * 2);
      ctx.fill();
      if (i % 3 === 0) {
        ctx.strokeStyle = rgba(color, 0.3);
        ctx.lineWidth = 0.8;
        ctx.stroke();
      }
    }
    ctx.restore();
  }
}

import { rgba, mulberry32, roundRect, clamp } from '../utils.js';
import { RESOURCE_META } from '../world.js';

function visible(r, x, y, pad = 180) {
  return x > r.cam.x - r.viewW / 2 - pad && x < r.cam.x + r.viewW / 2 + pad
    && y > r.cam.y - r.viewH / 2 - pad && y < r.cam.y + r.viewH / 2 + pad;
}

const CORAL_COLORS = ['#ff8f6b', '#ffb36b', '#d678ff', '#63e9d2', '#ff6f9c', '#ffd36b'];

export function drawDecorations(r, game) {
  const { ctx, time } = r;
  for (const d of game.world.decorations) {
    if (!visible(r, d.x, d.y, 260)) continue;
    if (d.type === 'kelp') drawKelp(r, d, time);
    else if (d.type === 'coral') drawCoral(r, d, time);
    else if (d.type === 'fan') drawFan(r, d, time);
    else if (d.type === 'anemone') drawAnemone(r, d, time);
    else if (d.type === 'glowplant') drawGlowPlant(r, d, time);
    else if (d.type === 'tube') drawTubeWorms(r, d, time);
  }
}

function drawKelp(r, d, time) {
  const { ctx } = r;
  const sway = Math.sin(time * 0.55 + d.phase) * (16 + d.height * 0.05);
  ctx.save();
  ctx.translate(d.x, d.y);
  const blades = 3;
  for (let b = 0; b < blades; b++) {
    const h = d.height * (0.62 + b * 0.19) * d.scale;
    const offset = (b - 1) * 8 * d.scale;
    const localSway = sway * (0.7 + b * 0.16);
    const g = ctx.createLinearGradient(0, 0, localSway, -h);
    g.addColorStop(0, 'rgba(10, 56, 46, 0.85)');
    g.addColorStop(0.45, 'rgba(20, 92, 68, 0.8)');
    g.addColorStop(1, 'rgba(72, 150, 96, 0.65)');
    ctx.strokeStyle = g;
    ctx.lineWidth = (5.5 - b) * d.scale;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(offset, 0);
    ctx.quadraticCurveTo(offset + localSway * 0.35, -h * 0.55, offset + localSway, -h);
    ctx.stroke();

    // Leaves.
    ctx.fillStyle = 'rgba(42, 117, 78, 0.55)';
    for (let i = 1; i <= 5; i++) {
      const t = i / 6;
      const lx = offset + localSway * t * t;
      const ly = -h * t;
      const side = i % 2 ? 1 : -1;
      ctx.save();
      ctx.translate(lx, ly);
      ctx.rotate(side * (0.7 + Math.sin(time * 0.7 + i) * 0.15));
      ctx.beginPath();
      ctx.ellipse(side * 8 * d.scale, 0, 13 * d.scale, 4.5 * d.scale, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
  }
  ctx.restore();
}

function coralBranches(d) {
  if (d._branches) return d._branches;
  const rng = mulberry32(d.seed || 1);
  const branches = [];
  const count = 4 + Math.floor(rng() * 3);
  for (let i = 0; i < count; i++) {
    const angle = -Math.PI / 2 + (i - count / 2) * 0.34 + (rng() - 0.5) * 0.2;
    const len = (38 + rng() * 45) * d.scale;
    const branch = { x0: (rng() - 0.5) * 10, y0: 0, angle, len, children: [] };
    for (let c = 0; c < 2; c++) {
      branch.children.push({
        t: 0.45 + rng() * 0.4,
        angle: angle + (c ? 1 : -1) * (0.45 + rng() * 0.4),
        len: len * (0.35 + rng() * 0.3),
      });
    }
    branches.push(branch);
  }
  d._branches = branches;
  return branches;
}

function drawCoral(r, d, time) {
  const { ctx } = r;
  const color = CORAL_COLORS[Math.floor(d.hue * CORAL_COLORS.length)];
  const branches = coralBranches(d);
  const sway = Math.sin(time * 0.8 + d.phase) * 0.03;
  ctx.save();
  ctx.translate(d.x, d.y);
  ctx.rotate(sway);
  ctx.lineCap = 'round';
  ctx.strokeStyle = color;
  ctx.globalAlpha = 0.75;
  for (const b of branches) {
    const ex = b.x0 + Math.cos(b.angle) * b.len;
    const ey = b.y0 + Math.sin(b.angle) * b.len;
    ctx.lineWidth = 5.5 * d.scale;
    ctx.beginPath();
    ctx.moveTo(b.x0, b.y0);
    ctx.quadraticCurveTo(b.x0 + Math.cos(b.angle) * b.len * 0.4 + 4, b.y0 + Math.sin(b.angle) * b.len * 0.6, ex, ey);
    ctx.stroke();
    for (const c of b.children) {
      const cx = b.x0 + (ex - b.x0) * c.t;
      const cy = b.y0 + (ey - b.y0) * c.t;
      ctx.lineWidth = 3 * d.scale;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(cx + Math.cos(c.angle) * c.len, cy + Math.sin(c.angle) * c.len);
      ctx.stroke();
    }
  }
  ctx.globalCompositeOperation = 'lighter';
  for (const b of branches) {
    const ex = b.x0 + Math.cos(b.angle) * b.len;
    const ey = b.y0 + Math.sin(b.angle) * b.len;
    const glow = ctx.createRadialGradient(ex, ey, 0, ex, ey, 9);
    glow.addColorStop(0, rgba(color, 0.45));
    glow.addColorStop(1, rgba(color, 0));
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(ex, ey, 9, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function drawFan(r, d, time) {
  const { ctx } = r;
  const color = CORAL_COLORS[Math.floor(d.hue * CORAL_COLORS.length)];
  const sway = Math.sin(time * 0.65 + d.phase) * 0.08;
  ctx.save();
  ctx.translate(d.x, d.y);
  ctx.rotate(sway);
  const size = 46 * d.scale;
  ctx.fillStyle = rgba(color, 0.15);
  ctx.strokeStyle = rgba(color, 0.55);
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.arc(0, 0, size, -Math.PI * 0.92, -Math.PI * 0.08);
  ctx.closePath();
  ctx.fill();
  for (let i = 0; i < 7; i++) {
    const a = -Math.PI * 0.9 + (i / 6) * Math.PI * 0.8;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(Math.cos(a) * size * 0.94, Math.sin(a) * size * 0.94);
    ctx.stroke();
    for (let j = 1; j < 4; j++) {
      const t = j / 4;
      const x = Math.cos(a) * size * t;
      const y = Math.sin(a) * size * t;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + Math.cos(a + 0.7) * 9, y + Math.sin(a + 0.7) * 9);
      ctx.stroke();
    }
  }
  ctx.restore();
}

function drawAnemone(r, d, time) {
  const { ctx } = r;
  const color = CORAL_COLORS[Math.floor(d.hue * CORAL_COLORS.length)];
  ctx.save();
  ctx.translate(d.x, d.y);
  ctx.lineCap = 'round';
  for (let i = 0; i < 9; i++) {
    const base = (i - 4) * 0.12;
    const sway = Math.sin(time * 1.3 + i * 1.7 + d.phase) * 0.35;
    const len = (26 + (i % 3) * 10) * d.scale;
    ctx.strokeStyle = rgba(color, 0.55);
    ctx.lineWidth = 2.4 * d.scale;
    ctx.beginPath();
    ctx.moveTo(base * 12, 0);
    ctx.quadraticCurveTo(base * 26 + sway * 8, -len * 0.55, base * 38 + sway * 14, -len);
    ctx.stroke();
    ctx.globalCompositeOperation = 'lighter';
    const gx = base * 38 + sway * 14;
    const gy = -len;
    const glow = ctx.createRadialGradient(gx, gy, 0, gx, gy, 6);
    glow.addColorStop(0, rgba(color, 0.5));
    glow.addColorStop(1, rgba(color, 0));
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(gx, gy, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
  }
  ctx.restore();
}

function drawGlowPlant(r, d, time) {
  const { ctx } = r;
  const color = d.zone === 'rift' ? '#ff8a4d' : d.hue > 0.5 ? '#7dffd6' : '#8f9bff';
  ctx.save();
  ctx.translate(d.x, d.y);
  for (let b = 0; b < 3; b++) {
    const h = d.height * (0.55 + b * 0.2);
    const sway = Math.sin(time * 0.7 + d.phase + b) * 10;
    ctx.strokeStyle = rgba(color, 0.42);
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo((b - 1) * 5, 0);
    ctx.quadraticCurveTo((b - 1) * 8 + sway * 0.4, -h * 0.55, (b - 1) * 10 + sway, -h);
    ctx.stroke();
    const gx = (b - 1) * 10 + sway;
    const gy = -h;
    ctx.globalCompositeOperation = 'lighter';
    const glow = ctx.createRadialGradient(gx, gy, 0, gx, gy, 14);
    glow.addColorStop(0, rgba(color, 0.5));
    glow.addColorStop(1, rgba(color, 0));
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(gx, gy, 14, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = rgba(color, 0.9);
    ctx.beginPath();
    ctx.arc(gx, gy, 2.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
  }
  ctx.restore();
}

function drawTubeWorms(r, d, time) {
  const { ctx } = r;
  ctx.save();
  ctx.translate(d.x, d.y);
  for (let i = 0; i < 5; i++) {
    const x = (i - 2) * 8 * d.scale;
    const h = d.height * (0.5 + (i % 3) * 0.22);
    const sway = Math.sin(time * 0.9 + i + d.phase) * 4;
    ctx.strokeStyle = 'rgba(110, 76, 72, 0.7)';
    ctx.lineWidth = 4.5 * d.scale;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.quadraticCurveTo(x + sway, -h * 0.6, x + sway, -h);
    ctx.stroke();
    ctx.fillStyle = 'rgba(255, 107, 92, 0.8)';
    ctx.beginPath();
    ctx.arc(x + sway, -h, 3.2 * d.scale, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

// ── Collectibles ──────────────────────────────────────────────────────
export function drawPickups(r, game) {
  const { ctx, time } = r;
  const nearest = game.nearestInteract;
  for (const node of game.world.nodes) {
    if (game.save.collectedNodes.includes(node.id)) continue;
    if (!visible(r, node.x, node.y, 120)) continue;
    const bob = Math.sin(time * 1.35 + node.phase) * 4;
    const active = nearest && nearest.id === node.id;
    drawNode(r, node, node.x, node.y + bob, active, time);
  }

  for (const chest of game.world.chests) {
    const opened = game.save.openedChests.includes(chest.id);
    if (!visible(r, chest.x, chest.y, 160)) continue;
    drawChest(r, chest, opened, nearest && nearest.id === chest.id, time);
  }

  for (const relic of game.world.relics) {
    if (game.save.relics.includes(relic.id)) continue;
    if (!visible(r, relic.x, relic.y, 260)) continue;
    drawRelic(r, relic, nearest && nearest.id === relic.id, time);
  }
}

function drawNode(r, node, x, y, active, time) {
  const { ctx } = r;
  const meta = RESOURCE_META[node.type] || RESOURCE_META.scrap;
  ctx.save();
  ctx.translate(x, y);

  // Ground / water glow.
  ctx.globalCompositeOperation = 'lighter';
  const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, active ? 62 : 44);
  glow.addColorStop(0, rgba(meta.glow, active ? 0.3 : 0.17));
  glow.addColorStop(1, rgba(meta.glow, 0));
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(0, 0, active ? 62 : 44, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';

  if (active) {
    ctx.strokeStyle = rgba(meta.color, 0.6);
    ctx.lineWidth = 1.2;
    ctx.setLineDash([5, 5]);
    ctx.lineDashOffset = -time * 18;
    ctx.beginPath();
    ctx.arc(0, 0, 30, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  if (node.type === 'scrap') {
    ctx.rotate(Math.sin(time * 0.7 + node.phase) * 0.12);
    for (let i = 0; i < 3; i++) {
      ctx.save();
      ctx.rotate(i * 1.1 + node.seed);
      ctx.fillStyle = i === 1 ? '#9fbac2' : '#c7dde2';
      ctx.strokeStyle = 'rgba(36, 62, 69, 0.7)';
      ctx.lineWidth = 1;
      roundRect(ctx, -12 + i * 5, -7 + (i % 2) * 7, 19, 10, 2);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = 'rgba(24, 52, 60, 0.8)';
      ctx.beginPath();
      ctx.arc(-7 + i * 5, -2 + (i % 2) * 7, 1.7, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
  } else if (node.type === 'pearl') {
    ctx.fillStyle = '#c99d70';
    ctx.strokeStyle = 'rgba(255, 231, 193, 0.5)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.ellipse(-8, 4, 13, 9, -0.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(8, 4, 13, 9, 0.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.globalCompositeOperation = 'lighter';
    const pg = ctx.createRadialGradient(0, -2, 0, 0, -2, 13);
    pg.addColorStop(0, 'rgba(255, 249, 226, 0.95)');
    pg.addColorStop(0.5, 'rgba(255, 216, 165, 0.6)');
    pg.addColorStop(1, 'rgba(255, 216, 165, 0)');
    ctx.fillStyle = pg;
    ctx.beginPath();
    ctx.arc(0, -2, 13, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = '#fff8e8';
    ctx.beginPath();
    ctx.arc(0, -2, 5, 0, Math.PI * 2);
    ctx.fill();
  } else if (node.type === 'crystal') {
    ctx.rotate(Math.sin(time * 0.6 + node.phase) * 0.2);
    const shards = [[0, -18, 7, 34], [-11, -8, 5, 24], [11, -10, 5, 26]];
    for (let i = 0; i < shards.length; i++) {
      const [sx, sy, w, h] = shards[i];
      const g = ctx.createLinearGradient(sx, sy, sx, sy + h);
      g.addColorStop(0, '#e8ffff');
      g.addColorStop(0.35, '#7eeaff');
      g.addColorStop(1, '#146b86');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.moveTo(sx, sy);
      ctx.lineTo(sx + w, sy + h * 0.4);
      ctx.lineTo(sx + w * 0.35, sy + h);
      ctx.lineTo(sx - w * 0.5, sy + h * 0.55);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = 'rgba(200, 255, 255, 0.45)';
      ctx.lineWidth = 0.8;
      ctx.stroke();
    }
  } else {
    ctx.fillStyle = 'rgba(13, 50, 47, 0.9)';
    roundRect(ctx, -13, -13, 26, 26, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(125, 255, 211, 0.6)';
    ctx.lineWidth = 1.4;
    ctx.stroke();
    ctx.fillStyle = '#8dffd3';
    ctx.fillRect(-2.5, -8, 5, 16);
    ctx.fillRect(-8, -2.5, 16, 5);
  }
  ctx.restore();
}

function drawChest(r, chest, opened, active, time) {
  const { ctx } = r;
  ctx.save();
  ctx.translate(chest.x, chest.y);
  const scale = chest.special ? 1.25 : 1;
  ctx.scale(scale, scale);
  ctx.fillStyle = 'rgba(0, 8, 12, 0.4)';
  ctx.beginPath();
  ctx.ellipse(0, 26, 34, 8, 0, 0, Math.PI * 2);
  ctx.fill();

  if (!opened) {
    ctx.globalCompositeOperation = 'lighter';
    const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, active ? 82 : 56);
    glow.addColorStop(0, `rgba(255, 202, 122, ${active ? 0.28 : 0.13})`);
    glow.addColorStop(1, 'rgba(255, 202, 122, 0)');
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(0, 0, active ? 82 : 56, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
  }

  if (active) {
    ctx.strokeStyle = 'rgba(255, 219, 154, 0.6)';
    ctx.lineWidth = 1.2;
    ctx.setLineDash([5, 5]);
    ctx.lineDashOffset = -time * 18;
    ctx.beginPath();
    ctx.arc(0, 0, 38, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // Chest body.
  const body = ctx.createLinearGradient(0, -6, 0, 26);
  body.addColorStop(0, opened ? '#3b2b21' : '#7a5230');
  body.addColorStop(1, opened ? '#1b1410' : '#3d2919');
  ctx.fillStyle = body;
  roundRect(ctx, -27, -2, 54, 27, 3);
  ctx.fill();
  ctx.strokeStyle = 'rgba(40, 24, 14, 0.8)';
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // Metal bands.
  ctx.fillStyle = opened ? 'rgba(126, 106, 74, 0.5)' : '#c69c58';
  ctx.fillRect(-27, 5, 54, 4);
  ctx.fillRect(-27, 18, 54, 4);
  ctx.fillRect(-20, -2, 5, 27);
  ctx.fillRect(15, -2, 5, 27);

  // Lid.
  ctx.save();
  if (opened) {
    ctx.translate(0, -4);
    ctx.rotate(-0.55);
    ctx.translate(0, 4);
  }
  const lid = ctx.createLinearGradient(0, -20, 0, 0);
  lid.addColorStop(0, opened ? '#4d3726' : '#9b6a3b');
  lid.addColorStop(1, opened ? '#2a1d14' : '#553a21');
  ctx.fillStyle = lid;
  ctx.beginPath();
  ctx.moveTo(-27, -2);
  ctx.quadraticCurveTo(-24, -20, 0, -20);
  ctx.quadraticCurveTo(24, -20, 27, -2);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(44, 27, 15, 0.8)';
  ctx.stroke();
  ctx.fillStyle = opened ? 'rgba(126, 106, 74, 0.5)' : '#c69c58';
  ctx.fillRect(-2, -18, 4, 17);
  ctx.restore();

  // Lock.
  if (!opened) {
    ctx.fillStyle = '#f0c26e';
    roundRect(ctx, -5, 2, 10, 11, 2);
    ctx.fill();
    ctx.fillStyle = '#5b3d1e';
    ctx.beginPath();
    ctx.arc(0, 7, 1.7, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillRect(-0.8, 7, 1.6, 4);
  } else {
    ctx.globalCompositeOperation = 'lighter';
    const inner = ctx.createRadialGradient(0, 4, 0, 0, 4, 22);
    inner.addColorStop(0, 'rgba(255, 216, 140, 0.22)');
    inner.addColorStop(1, 'rgba(255, 216, 140, 0)');
    ctx.fillStyle = inner;
    ctx.beginPath();
    ctx.arc(0, 4, 22, 0, Math.PI * 2);
    ctx.fill();
  }

  // Sparkles.
  if (!opened) {
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 3; i++) {
      const a = time * 1.5 + i * 2.1 + chest.phase;
      const sx = Math.cos(a) * (22 + i * 5);
      const sy = Math.sin(a * 1.3) * (12 + i * 3) - 10;
      const alpha = 0.25 + Math.sin(a * 2) * 0.2;
      ctx.fillStyle = `rgba(255, 235, 180, ${alpha})`;
      ctx.beginPath();
      ctx.arc(sx, sy, 1.2, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();
}

function drawRelic(r, relic, active, time) {
  const { ctx } = r;
  const bob = Math.sin(time * 1.15 + relic.phase) * 7;
  ctx.save();
  ctx.translate(relic.x, relic.y + bob);

  // Beacon.
  ctx.globalCompositeOperation = 'lighter';
  const beam = ctx.createLinearGradient(0, 0, 0, -520);
  beam.addColorStop(0, 'rgba(255, 208, 122, 0.2)');
  beam.addColorStop(0.5, 'rgba(255, 208, 122, 0.05)');
  beam.addColorStop(1, 'rgba(255, 208, 122, 0)');
  ctx.fillStyle = beam;
  ctx.beginPath();
  ctx.moveTo(-28, 0);
  ctx.lineTo(-7, -520);
  ctx.lineTo(10, -520);
  ctx.lineTo(28, 0);
  ctx.closePath();
  ctx.fill();

  const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, active ? 150 : 110);
  glow.addColorStop(0, 'rgba(255, 240, 198, 0.4)');
  glow.addColorStop(0.28, 'rgba(255, 202, 122, 0.18)');
  glow.addColorStop(1, 'rgba(255, 202, 122, 0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(0, 0, active ? 150 : 110, 0, Math.PI * 2);
  ctx.fill();

  // Orbits.
  ctx.strokeStyle = 'rgba(255, 222, 158, 0.4)';
  ctx.lineWidth = 1.2;
  for (let i = 0; i < 3; i++) {
    const a = time * (0.25 + i * 0.08) + i * 2.1;
    const rr = 48 + i * 13;
    ctx.beginPath();
    ctx.ellipse(0, 0, rr, rr * 0.33, a, 0, Math.PI * 2);
    ctx.stroke();
  }

  ctx.globalCompositeOperation = 'source-over';
  ctx.rotate(Math.sin(time * 0.5 + relic.phase) * 0.12);
  const shard = ctx.createLinearGradient(-18, -34, 18, 34);
  shard.addColorStop(0, '#fff9e5');
  shard.addColorStop(0.4, '#ffe2a4');
  shard.addColorStop(0.7, '#d9994f');
  shard.addColorStop(1, '#6c3c1c');
  ctx.fillStyle = shard;
  ctx.beginPath();
  ctx.moveTo(0, -40);
  ctx.lineTo(19, -12);
  ctx.lineTo(10, 33);
  ctx.lineTo(-10, 33);
  ctx.lineTo(-19, -12);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(255, 246, 220, 0.65)';
  ctx.lineWidth = 1.4;
  ctx.stroke();

  // Inner glyph.
  ctx.strokeStyle = 'rgba(72, 34, 14, 0.55)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(0, -24);
  ctx.lineTo(0, 20);
  ctx.moveTo(-8, -8);
  ctx.lineTo(8, -8);
  ctx.moveTo(-7, 8);
  ctx.lineTo(7, 8);
  ctx.stroke();

  // Gold frame.
  ctx.strokeStyle = 'rgba(255, 220, 150, 0.75)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(0, -2, 31, 0.35, Math.PI * 1.65);
  ctx.stroke();

  if (active) {
    ctx.strokeStyle = 'rgba(255, 230, 178, 0.65)';
    ctx.setLineDash([4, 6]);
    ctx.lineDashOffset = -time * 20;
    ctx.beginPath();
    ctx.arc(0, 0, 52, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
  }
  ctx.restore();
}

import { clamp, rgba, roundRect } from '../utils.js';
import { zoneAtY } from '../world.js';

const CREATURE_COLORS = {
  shark: { body: '#2e6571', dark: '#123a48', light: '#7ba6a9', belly: '#b6d2cf' },
  angler: { body: '#1b2730', dark: '#070e14', light: '#42606a', glow: '#9cf7ff' },
  guardian: { body: '#20141f', dark: '#07050a', light: '#54364f', glow: '#ffbd7a' },
  eel: { body: '#1c2d2f', dark: '#071012', light: '#4d7d76', glow: '#7dffd6' },
};

function visible(r, x, y, pad = 180) {
  return x > r.cam.x - r.viewW / 2 - pad && x < r.cam.x + r.viewW / 2 + pad
    && y > r.cam.y - r.viewH / 2 - pad && y < r.cam.y + r.viewH / 2 + pad;
}

function glow(r, x, y, radius, color, alpha) {
  const { ctx } = r;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(x, y, 0, x, y, radius);
  g.addColorStop(0, rgba(color, alpha));
  g.addColorStop(1, rgba(color, 0));
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

export function drawSchools(r, game) {
  const { ctx, time } = r;
  for (const school of game.world.schools) {
    if (!visible(r, school.x, school.y, 260)) continue;
    const dir = school.dir;
    ctx.save();
    for (let i = 0; i < school.count; i++) {
      const t = time * 1.2 + i * 0.8 + school.phase;
      const ox = (i - school.count / 2) * 12 + Math.sin(t * 1.3) * 6;
      const oy = Math.sin(t * 1.7 + i) * 8 + (i % 3 - 1) * 5;
      const x = school.x + ox;
      const y = school.y + oy;
      const scale = 0.75 + (i % 3) * 0.16;
      ctx.save();
      ctx.translate(x, y);
      ctx.scale(dir * scale, scale);
      ctx.rotate(Math.sin(t * 2 + i) * 0.08);
      if (school.type === 'gold') ctx.fillStyle = 'rgba(255, 203, 120, 0.8)';
      else if (school.type === 'lantern') ctx.fillStyle = 'rgba(130, 168, 196, 0.8)';
      else ctx.fillStyle = 'rgba(168, 219, 224, 0.72)';
      ctx.beginPath();
      ctx.ellipse(0, 0, 8, 3.4, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(-7, 0);
      ctx.lineTo(-13, -4.5);
      ctx.lineTo(-12, 4.5);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = 'rgba(6, 22, 28, 0.8)';
      ctx.beginPath();
      ctx.arc(4, -0.7, 0.9, 0, Math.PI * 2);
      ctx.fill();
      if (school.type === 'lantern') {
        ctx.globalCompositeOperation = 'lighter';
        ctx.fillStyle = 'rgba(130, 246, 255, 0.7)';
        ctx.beginPath();
        ctx.arc(2, 3.2, 1.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalCompositeOperation = 'source-over';
      }
      ctx.restore();
    }
    ctx.restore();
  }
}

export function drawCreatures(r, game) {
  const { ctx, time } = r;
  for (const c of game.creatures) {
    if (!visible(r, c.x, c.y, c.size * 3 + 160)) continue;
    if (c.type === 'jelly') drawJelly(r, c, time);
    else if (c.type === 'shark') drawShark(r, c, time);
    else if (c.type === 'angler') drawAngler(r, c, time, false);
    else if (c.type === 'guardian') drawAngler(r, c, time, true);
    else if (c.type === 'eel') drawEel(r, c, time);
    else if (c.type === 'ray') drawRay(r, c, time);
    else if (c.type === 'urchin') drawUrchin(r, c, time);

    if (c.stun > 0) drawStun(r, c, time);
  }
}

function drawJelly(r, c, time) {
  const { ctx } = r;
  const pulse = 1 + Math.sin(c.phase * 1.4) * 0.07;
  const color = c.glow === 'violet' ? '#b69bff' : c.glow === 'amber' ? '#ffb36b' : '#7ef6ff';
  ctx.save();
  ctx.translate(c.x, c.y);
  glow(r, 0, 0, c.size * 2.6, color, 0.16);

  // Tentacles.
  ctx.lineCap = 'round';
  for (let i = 0; i < 6; i++) {
    const base = (i - 2.5) * c.size * 0.28;
    const sway = Math.sin(time * 1.2 + i * 1.4 + c.phase) * 12;
    const len = c.tentacle * (0.6 + (i % 3) * 0.2);
    ctx.strokeStyle = rgba(color, 0.36);
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(base, c.size * 0.5);
    ctx.bezierCurveTo(base + sway * 0.4, c.size + len * 0.3, base - sway, c.size + len * 0.7, base + sway * 0.6, c.size + len);
    ctx.stroke();
    // Tentacle light beads.
    ctx.globalCompositeOperation = 'lighter';
    for (let j = 1; j <= 3; j++) {
      const t = j / 4;
      const x = base + Math.sin(time * 1.2 + i + j) * 8 * t;
      const y = c.size * 0.5 + len * t;
      ctx.fillStyle = rgba(color, 0.3 - t * 0.05);
      ctx.beginPath();
      ctx.arc(x, y, 1.4, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalCompositeOperation = 'source-over';
  }

  // Bell.
  ctx.scale(pulse, pulse);
  const bell = ctx.createLinearGradient(0, -c.size, 0, c.size);
  bell.addColorStop(0, rgba(color, 0.75));
  bell.addColorStop(0.55, rgba(color, 0.26));
  bell.addColorStop(1, rgba(color, 0.08));
  ctx.fillStyle = bell;
  ctx.beginPath();
  ctx.moveTo(-c.size, 4);
  ctx.bezierCurveTo(-c.size * 1.05, -c.size * 1.1, c.size * 1.05, -c.size * 1.1, c.size, 4);
  ctx.quadraticCurveTo(c.size * 0.55, c.size * 0.65, 0, c.size * 0.55);
  ctx.quadraticCurveTo(-c.size * 0.55, c.size * 0.65, -c.size, 4);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = rgba(color, 0.55);
  ctx.lineWidth = 1.3;
  ctx.stroke();

  // Inner organs.
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 4; i++) {
    const a = time * 0.8 + i * 1.6;
    ctx.fillStyle = rgba(color, 0.24);
    ctx.beginPath();
    ctx.arc(Math.cos(a) * c.size * 0.3, Math.sin(a) * c.size * 0.15, 2.6, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.strokeStyle = rgba(color, 0.3);
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(0, 0, c.size * 0.72, Math.PI * 1.08, Math.PI * 1.92);
  ctx.stroke();
  ctx.restore();
}

function drawShark(r, c, time) {
  const { ctx } = r;
  const col = CREATURE_COLORS.shark;
  ctx.save();
  ctx.translate(c.x, c.y);
  ctx.scale(c.dir, 1);
  ctx.rotate(clamp(c.vy / 600, -0.35, 0.35));
  const wag = Math.sin(time * 5.2 + c.phase) * 6;

  // Body.
  const body = ctx.createLinearGradient(0, -22, 0, 22);
  body.addColorStop(0, col.light);
  body.addColorStop(0.4, col.body);
  body.addColorStop(1, col.belly);
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(58, 0);
  ctx.quadraticCurveTo(42, -19, 8, -20);
  ctx.quadraticCurveTo(-34, -18, -62, wag * 0.25);
  ctx.quadraticCurveTo(-38, 18, 8, 20);
  ctx.quadraticCurveTo(44, 18, 58, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(6, 24, 31, 0.45)';
  ctx.lineWidth = 1.4;
  ctx.stroke();

  // Tail.
  ctx.fillStyle = col.body;
  ctx.beginPath();
  ctx.moveTo(-58, 0);
  ctx.lineTo(-96, -24 + wag);
  ctx.lineTo(-80, 1);
  ctx.lineTo(-96, 24 + wag);
  ctx.closePath();
  ctx.fill();

  // Dorsal fin.
  ctx.fillStyle = col.dark;
  ctx.beginPath();
  ctx.moveTo(6, -19);
  ctx.lineTo(-16, -54);
  ctx.lineTo(-34, -18);
  ctx.closePath();
  ctx.fill();
  // Pectoral fin.
  ctx.beginPath();
  ctx.moveTo(10, 17);
  ctx.lineTo(-8, 48);
  ctx.lineTo(-26, 18);
  ctx.closePath();
  ctx.fill();

  // Gill slits.
  ctx.strokeStyle = 'rgba(8, 35, 43, 0.5)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(22 + i * 5, -10);
    ctx.quadraticCurveTo(25 + i * 5, 0, 22 + i * 5, 10);
    ctx.stroke();
  }

  // Eye.
  ctx.fillStyle = '#e9f5ef';
  ctx.beginPath();
  ctx.arc(40, -6, 3.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#071115';
  ctx.beginPath();
  ctx.arc(41, -6, 1.9, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
  ctx.beginPath();
  ctx.arc(41.7, -6.7, 0.7, 0, Math.PI * 2);
  ctx.fill();

  // Teeth.
  ctx.strokeStyle = 'rgba(232, 245, 239, 0.55)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(50, 4);
  for (let i = 0; i < 5; i++) {
    ctx.lineTo(52 - i * 3, 4 + (i % 2 ? 2.5 : 0));
  }
  ctx.stroke();

  // Scars.
  ctx.strokeStyle = 'rgba(178, 210, 206, 0.24)';
  ctx.lineWidth = 1.1;
  ctx.beginPath();
  ctx.moveTo(-8, -12);
  ctx.lineTo(3, -5);
  ctx.moveTo(-14, 8);
  ctx.lineTo(-3, 14);
  ctx.stroke();

  if (c.state === 'chase') {
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(52, 0, 0, 52, 0, 30);
    g.addColorStop(0, 'rgba(255, 130, 110, 0.14)');
    g.addColorStop(1, 'rgba(255, 130, 110, 0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(52, 0, 30, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function drawAngler(r, c, time, guardian) {
  const { ctx } = r;
  const col = guardian ? CREATURE_COLORS.guardian : CREATURE_COLORS.angler;
  const size = c.size;
  const open = 0.5 + Math.sin(time * 1.3 + c.phase) * 0.12;
  ctx.save();
  ctx.translate(c.x, c.y);
  ctx.scale(c.dir, 1);
  ctx.rotate(clamp(c.vy / 700, -0.2, 0.2));

  if (guardian) glow(r, 0, 0, size * 3.4, col.glow, 0.09);

  // Tail.
  ctx.fillStyle = col.dark;
  ctx.beginPath();
  ctx.moveTo(-size * 0.8, 0);
  ctx.lineTo(-size * 1.55, -size * 0.42);
  ctx.lineTo(-size * 1.32, 0);
  ctx.lineTo(-size * 1.55, size * 0.42);
  ctx.closePath();
  ctx.fill();

  // Body.
  const body = ctx.createRadialGradient(-size * 0.2, -size * 0.35, size * 0.1, 0, 0, size * 1.35);
  body.addColorStop(0, col.light);
  body.addColorStop(0.45, col.body);
  body.addColorStop(1, col.dark);
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.ellipse(0, 0, size * 1.1, size * 0.86, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = 'rgba(0, 0, 0, 0.35)';
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // Jaw.
  ctx.fillStyle = '#05080b';
  ctx.beginPath();
  ctx.moveTo(size * 0.55, -size * 0.18);
  ctx.quadraticCurveTo(size * 1.35, -size * 0.1, size * 1.18, size * 0.22);
  ctx.quadraticCurveTo(size * 0.8, size * 0.45, size * 0.45, size * 0.2);
  ctx.closePath();
  ctx.fill();

  // Teeth.
  ctx.fillStyle = 'rgba(235, 242, 225, 0.82)';
  for (let i = 0; i < 7; i++) {
    const x = size * 0.62 + i * size * 0.075;
    const y = -size * 0.1 + Math.sin(i * 0.9) * 2;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + size * 0.035, y + size * (0.09 + open * 0.04));
    ctx.lineTo(x + size * 0.07, y);
    ctx.closePath();
    ctx.fill();
  }
  for (let i = 0; i < 5; i++) {
    const x = size * 0.7 + i * size * 0.085;
    const y = size * 0.16;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + size * 0.03, y - size * 0.075);
    ctx.lineTo(x + size * 0.065, y);
    ctx.closePath();
    ctx.fill();
  }

  // Eye.
  ctx.fillStyle = 'rgba(226, 246, 238, 0.85)';
  ctx.beginPath();
  ctx.arc(size * 0.35, -size * 0.3, size * 0.13, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#071013';
  ctx.beginPath();
  ctx.arc(size * 0.37, -size * 0.3, size * 0.075, 0, Math.PI * 2);
  ctx.fill();

  // Fins.
  ctx.fillStyle = col.dark;
  ctx.beginPath();
  ctx.moveTo(-size * 0.2, -size * 0.75);
  ctx.lineTo(-size * 0.55, -size * 1.18);
  ctx.lineTo(-size * 0.65, -size * 0.55);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(-size * 0.05, size * 0.7);
  ctx.lineTo(-size * 0.35, size * 1.15);
  ctx.lineTo(-size * 0.6, size * 0.6);
  ctx.closePath();
  ctx.fill();

  // Lure.
  ctx.strokeStyle = 'rgba(180, 205, 200, 0.55)';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(size * 0.1, -size * 0.8);
  ctx.quadraticCurveTo(size * 0.35, -size * 1.65, size * 0.75, -size * 1.5);
  ctx.stroke();
  const lx = size * 0.75;
  const ly = -size * 1.5;
  glow(r, lx, ly, size * (guardian ? 1.2 : 0.8), col.glow, 0.5);
  ctx.fillStyle = '#fffef0';
  ctx.beginPath();
  ctx.arc(lx, ly, size * 0.1, 0, Math.PI * 2);
  ctx.fill();

  if (guardian) {
    // Crown of smaller lures.
    for (let i = 0; i < 4; i++) {
      const a = -Math.PI / 2 + (i - 1.5) * 0.5;
      const x = Math.cos(a) * size * 0.75;
      const y = Math.sin(a) * size * 0.75 - size * 0.2;
      glow(r, x, y, size * 0.42, col.glow, 0.4);
      ctx.fillStyle = '#ffe8c2';
      ctx.beginPath();
      ctx.arc(x, y, 2.4, 0, Math.PI * 2);
      ctx.fill();
    }
    // Ancient markings.
    ctx.strokeStyle = 'rgba(255, 189, 122, 0.28)';
    ctx.lineWidth = 1.4;
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.arc(-size * 0.15, 0, size * (0.25 + i * 0.14), -0.9, 0.9);
      ctx.stroke();
    }
  }
  ctx.restore();
}

function drawEel(r, c, time) {
  const { ctx } = r;
  const col = CREATURE_COLORS.eel;
  const len = c.size * 4;
  ctx.save();
  ctx.translate(c.x, c.y);
  ctx.rotate(c.angle);
  const segments = 14;
  const amp = c.state === 'lunge' ? 8 : 15;
  const speed = c.state === 'lunge' ? 14 : 5.5;
  const pts = [];
  for (let i = 0; i < segments; i++) {
    const t = i / (segments - 1);
    const x = -t * len;
    const y = Math.sin(time * speed - t * 4.2 + c.phase) * amp * t;
    pts.push([x, y]);
  }
  // Body segments, back to front.
  for (let i = segments - 1; i >= 0; i--) {
    const t = i / (segments - 1);
    const [x, y] = pts[i];
    const rad = (1 - t) * c.size * 0.55 + 1.5;
    const g = ctx.createRadialGradient(x - rad * 0.3, y - rad * 0.4, 0, x, y, rad * 1.3);
    g.addColorStop(0, col.light);
    g.addColorStop(0.5, col.body);
    g.addColorStop(1, col.dark);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, rad, 0, Math.PI * 2);
    ctx.fill();
    if (i % 3 === 0) {
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = rgba(col.glow, 0.18);
      ctx.beginPath();
      ctx.arc(x, y - rad * 0.2, rad * 0.45, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalCompositeOperation = 'source-over';
    }
  }
  // Head.
  const [hx, hy] = pts[0];
  ctx.fillStyle = col.body;
  ctx.beginPath();
  ctx.ellipse(hx + 4, hy, c.size * 0.8, c.size * 0.55, 0, 0, Math.PI * 2);
  ctx.fill();
  // Jaw.
  const jaw = c.state === 'lunge' ? 0.55 : 0.1;
  ctx.strokeStyle = 'rgba(180, 220, 210, 0.45)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(hx + 18, hy + 1);
  ctx.lineTo(hx + 34, hy + 2 + jaw * 6);
  ctx.stroke();
  ctx.fillStyle = '#061012';
  ctx.beginPath();
  ctx.moveTo(hx + 18, hy + 1);
  ctx.lineTo(hx + 34, hy + 2 + jaw * 6);
  ctx.lineTo(hx + 22, hy + 6);
  ctx.closePath();
  ctx.fill();
  // Eye.
  glow(r, hx + 12, hy - 4, 9, col.glow, 0.4);
  ctx.fillStyle = '#dffdf3';
  ctx.beginPath();
  ctx.arc(hx + 12, hy - 4, 2.6, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#061010';
  ctx.beginPath();
  ctx.arc(hx + 12.6, hy - 4, 1.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function drawRay(r, c, time) {
  const { ctx } = r;
  ctx.save();
  ctx.translate(c.x, c.y);
  ctx.scale(c.dir, 1);
  ctx.rotate(c.angle || 0);
  const flap = Math.sin(time * 2.1 + c.phase) * 0.5;
  const s = c.size;
  const g = ctx.createLinearGradient(0, -s, 0, s);
  g.addColorStop(0, 'rgba(88, 118, 120, 0.7)');
  g.addColorStop(1, 'rgba(26, 47, 51, 0.85)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(0, -s * 0.15);
  ctx.quadraticCurveTo(-s * 0.7, -s * (0.7 + flap), -s * 1.1, -s * 0.18);
  ctx.quadraticCurveTo(-s * 0.5, s * 0.28, 0, s * 0.12);
  ctx.quadraticCurveTo(s * 0.5, s * 0.28, s * 1.1, -s * 0.18);
  ctx.quadraticCurveTo(s * 0.7, -s * (0.7 + flap), 0, -s * 0.15);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(150, 200, 196, 0.2)';
  ctx.lineWidth = 1;
  ctx.stroke();
  // Tail.
  ctx.strokeStyle = 'rgba(82, 116, 114, 0.6)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-s * 0.9, 0);
  ctx.quadraticCurveTo(-s * 1.6, s * 0.25, -s * 2.1, s * 0.08);
  ctx.stroke();
  // Eyes.
  ctx.fillStyle = 'rgba(200, 232, 226, 0.7)';
  ctx.beginPath();
  ctx.arc(s * 0.1, -s * 0.16, 2, 0, Math.PI * 2);
  ctx.arc(s * 0.1, s * 0.16, 2, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function drawUrchin(r, c, time) {
  const { ctx } = r;
  ctx.save();
  ctx.translate(c.x, c.y);
  const spikes = 18;
  ctx.strokeStyle = 'rgba(94, 44, 88, 0.85)';
  ctx.lineWidth = 2;
  for (let i = 0; i < spikes; i++) {
    const a = (i / spikes) * Math.PI * 2 + Math.sin(time * 0.6 + c.phase) * 0.04;
    const len = c.size * (1.4 + (i % 3) * 0.25);
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * c.size * 0.5, Math.sin(a) * c.size * 0.5);
    ctx.lineTo(Math.cos(a) * len, Math.sin(a) * len);
    ctx.stroke();
    if (i % 4 === 0) {
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = 'rgba(255, 110, 180, 0.45)';
      ctx.beginPath();
      ctx.arc(Math.cos(a) * len, Math.sin(a) * len, 1.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalCompositeOperation = 'source-over';
    }
  }
  const g = ctx.createRadialGradient(-c.size * 0.3, -c.size * 0.3, 1, 0, 0, c.size);
  g.addColorStop(0, '#6e2b5f');
  g.addColorStop(1, '#200a22');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, c.size * 0.68, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function drawStun(r, c, time) {
  const { ctx } = r;
  ctx.save();
  ctx.translate(c.x, c.y);
  ctx.globalCompositeOperation = 'lighter';
  ctx.strokeStyle = `rgba(150, 235, 255, ${0.18 + Math.sin(time * 8) * 0.08})`;
  ctx.lineWidth = 1.2;
  for (let i = 0; i < 3; i++) {
    const rr = c.size * (1.3 + i * 0.28);
    ctx.beginPath();
    ctx.arc(0, 0, rr, time * 1.5 + i * 2, time * 1.5 + i * 2 + 1.1);
    ctx.stroke();
  }
  ctx.restore();
}

import { clamp, rgba, roundRect } from '../utils.js';

export function drawPlayer(r, game) {
  const { ctx, time } = r;
  const p = game.player;
  const bob = Math.sin(time * 2.2) * 1.6;
  const flicker = p.invuln > 0 && Math.floor(time * 18) % 2 === 0;

  ctx.save();
  ctx.translate(p.x, p.y + bob);
  ctx.rotate(p.angle);
  ctx.globalAlpha = flicker ? 0.55 : 1;

  // Thruster halo.
  ctx.globalCompositeOperation = 'lighter';
  const thrust = ctx.createRadialGradient(-40, 0, 0, -40, 0, p.boosting ? 54 : 32);
  thrust.addColorStop(0, `rgba(130, 240, 255, ${p.boosting ? 0.35 : 0.18})`);
  thrust.addColorStop(1, 'rgba(130, 240, 255, 0)');
  ctx.fillStyle = thrust;
  ctx.beginPath();
  ctx.arc(-40, 0, p.boosting ? 54 : 32, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';

  // Rear fins.
  ctx.fillStyle = '#143c46';
  ctx.beginPath();
  ctx.moveTo(-24, -12);
  ctx.lineTo(-42, -34);
  ctx.lineTo(-50, -10);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(-24, 12);
  ctx.lineTo(-42, 34);
  ctx.lineTo(-50, 10);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(120, 220, 220, 0.3)';
  ctx.lineWidth = 1;
  ctx.stroke();

  // Main hull.
  const hull = ctx.createLinearGradient(0, -16, 0, 16);
  hull.addColorStop(0, '#d9f3f0');
  hull.addColorStop(0.22, '#8cb9b8');
  hull.addColorStop(0.55, '#3f7378');
  hull.addColorStop(1, '#12363f');
  ctx.fillStyle = hull;
  roundRect(ctx, -36, -14, 72, 28, 14);
  ctx.fill();
  ctx.strokeStyle = 'rgba(8, 32, 39, 0.6)';
  ctx.lineWidth = 1.3;
  ctx.stroke();

  // Belly stripe.
  ctx.fillStyle = 'rgba(255, 184, 94, 0.85)';
  ctx.beginPath();
  ctx.moveTo(-20, 11);
  ctx.quadraticCurveTo(10, 15, 30, 8);
  ctx.lineTo(29, 11);
  ctx.quadraticCurveTo(8, 18, -20, 14);
  ctx.closePath();
  ctx.fill();

  // Panel lines and rivets.
  ctx.strokeStyle = 'rgba(9, 38, 44, 0.38)';
  ctx.lineWidth = 0.9;
  ctx.beginPath();
  ctx.moveTo(-18, -13);
  ctx.lineTo(-18, 12);
  ctx.moveTo(18, -12);
  ctx.lineTo(18, 12);
  ctx.stroke();
  ctx.fillStyle = 'rgba(220, 250, 248, 0.55)';
  for (const [x, y] of [[-24, -8], [-24, 7], [23, -7], [23, 8]]) {
    ctx.beginPath();
    ctx.arc(x, y, 0.9, 0, Math.PI * 2);
    ctx.fill();
  }

  // Cockpit.
  const glass = ctx.createRadialGradient(9, -7, 1, 8, 0, 15);
  glass.addColorStop(0, 'rgba(222, 255, 255, 0.95)');
  glass.addColorStop(0.3, 'rgba(96, 228, 238, 0.8)');
  glass.addColorStop(0.75, 'rgba(17, 94, 113, 0.9)');
  glass.addColorStop(1, 'rgba(6, 39, 53, 0.95)');
  ctx.fillStyle = glass;
  ctx.beginPath();
  ctx.ellipse(9, 0, 13.5, 11.5, -0.08, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = 'rgba(208, 255, 255, 0.55)';
  ctx.lineWidth = 1;
  ctx.stroke();
  // Glass highlight.
  ctx.fillStyle = 'rgba(255, 255, 255, 0.55)';
  ctx.beginPath();
  ctx.ellipse(5, -5, 4.5, 2.4, -0.6, 0, Math.PI * 2);
  ctx.fill();
  // Pilot silhouette.
  ctx.fillStyle = 'rgba(5, 33, 43, 0.5)';
  ctx.beginPath();
  ctx.ellipse(10, 2, 4, 5, 0.1, 0, Math.PI * 2);
  ctx.fill();

  // Headlamp housing.
  ctx.fillStyle = '#1c4a52';
  roundRect(ctx, 30, -5.5, 9, 11, 2);
  ctx.fill();
  ctx.fillStyle = '#d8ffff';
  ctx.beginPath();
  ctx.arc(38, 0, 4.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalCompositeOperation = 'lighter';
  const lampGlow = ctx.createRadialGradient(39, 0, 0, 39, 0, 22);
  lampGlow.addColorStop(0, 'rgba(220, 255, 255, 0.6)');
  lampGlow.addColorStop(1, 'rgba(180, 250, 255, 0)');
  ctx.fillStyle = lampGlow;
  ctx.beginPath();
  ctx.arc(39, 0, 22, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';

  // Nose skid.
  ctx.strokeStyle = 'rgba(150, 220, 220, 0.3)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(34, 8);
  ctx.quadraticCurveTo(44, 9, 50, 4);
  ctx.stroke();

  // Propeller.
  ctx.save();
  ctx.translate(-38, 0);
  const spin = time * (p.boosting ? 26 : 12);
  ctx.rotate(spin);
  ctx.fillStyle = 'rgba(160, 210, 210, 0.7)';
  for (let i = 0; i < 3; i++) {
    ctx.save();
    ctx.rotate((i / 3) * Math.PI * 2);
    ctx.beginPath();
    ctx.ellipse(0, -7, 2.2, 7, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
  ctx.fillStyle = '#8fb7b6';
  ctx.beginPath();
  ctx.arc(0, 0, 3, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // Hull number.
  ctx.save();
  ctx.translate(-4, 1);
  ctx.rotate(Math.PI / 2);
  ctx.font = '5.5px "Outfit", sans-serif';
  ctx.fillStyle = 'rgba(215, 250, 248, 0.55)';
  ctx.textAlign = 'center';
  ctx.fillText('N–07', 0, 0);
  ctx.restore();

  // Damage flash.
  if (p.hitFlash > 0) {
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = `rgba(255, 60, 50, ${clamp(p.hitFlash * 0.5, 0, 0.45)})`;
    roundRect(ctx, -36, -14, 72, 28, 14);
    ctx.fill();
  }

  ctx.restore();

  // Bubble halo around the sub.
  if (p.boosting) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = 'rgba(180, 250, 255, 0.16)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 3; i++) {
      const t = (time * 2 + i * 0.33) % 1;
      ctx.beginPath();
      ctx.arc(p.x, p.y, 24 + t * 46, 0, Math.PI * 2);
      ctx.globalAlpha = (1 - t) * 0.4;
      ctx.stroke();
    }
    ctx.restore();
  }
}

export function drawParticles(r, game) {
  const { ctx } = r;
  ctx.save();
  for (const p of game.particles.items) {
    const life = clamp(p.life / p.maxLife, 0, 1);
    if (p.kind === 'bubble') {
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = `rgba(190, 250, 255, ${0.4 * life * (p.alpha || 1)})`;
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
      ctx.stroke();
      ctx.fillStyle = `rgba(210, 255, 255, ${0.1 * life})`;
      ctx.fill();
      ctx.fillStyle = `rgba(255, 255, 255, ${0.5 * life})`;
      ctx.beginPath();
      ctx.arc(p.x - p.size * 0.28, p.y - p.size * 0.3, Math.max(0.4, p.size * 0.22), 0, Math.PI * 2);
      ctx.fill();
    } else {
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = rgba(p.color, 0.85 * life);
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * life, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = rgba(p.color, 0.18 * life);
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * 3 * life, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();
}

export function drawEffects(r, game) {
  const { ctx } = r;
  for (const e of game.effects) {
    const t = 1 - e.life / e.maxLife;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    if (e.type === 'pulse') {
      const rad = e.radius * (0.15 + t * 0.95);
      const alpha = (1 - t) * 0.55;
      ctx.strokeStyle = `rgba(160, 250, 255, ${alpha})`;
      ctx.lineWidth = 3 * (1 - t) + 0.6;
      ctx.beginPath();
      ctx.arc(e.x, e.y, rad, 0, Math.PI * 2);
      ctx.stroke();
      ctx.strokeStyle = `rgba(120, 220, 255, ${alpha * 0.45})`;
      ctx.lineWidth = 8 * (1 - t) + 0.4;
      ctx.beginPath();
      ctx.arc(e.x, e.y, rad * 0.82, 0, Math.PI * 2);
      ctx.stroke();
      const g = ctx.createRadialGradient(e.x, e.y, rad * 0.6, e.x, e.y, rad);
      g.addColorStop(0, 'rgba(120, 235, 255, 0)');
      g.addColorStop(0.8, `rgba(120, 235, 255, ${alpha * 0.15})`);
      g.addColorStop(1, 'rgba(120, 235, 255, 0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(e.x, e.y, rad, 0, Math.PI * 2);
      ctx.fill();
    } else if (e.type === 'sonar') {
      const rad = e.radius * t;
      ctx.strokeStyle = `rgba(125, 240, 207, ${(1 - t) * 0.5})`;
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.arc(e.x, e.y, rad, 0, Math.PI * 2);
      ctx.stroke();
      ctx.strokeStyle = `rgba(125, 240, 207, ${(1 - t) * 0.18})`;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(e.x, e.y, rad * 0.65, 0, Math.PI * 2);
      ctx.stroke();
    } else if (e.type === 'pickup') {
      ctx.strokeStyle = rgba(e.color || '#9ffbff', (1 - t) * 0.55);
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.arc(e.x, e.y, 12 + t * 34, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
  }
}

import { clamp } from '../utils.js';
import {
  drawBackground, drawLighting, drawSnow, updateSnow, drawMinimap,
} from './background.js';
import {
  drawSeabed, drawRocks, drawLandmarks, drawVents, drawSurfaceAndBoat,
} from './terrain.js';
import { drawDecorations, drawPickups } from './flora.js';
import { drawSchools, drawCreatures } from './creatures.js';
import { drawPlayer, drawParticles, drawEffects } from './player.js';

export class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.w = 1;
    this.h = 1;
    this.dpr = 1;
    this.zoom = 1;
    this.viewW = 1440;
    this.viewH = 810;
    this.cam = { x: 0, y: 0 };
    this.snow = [];
    this.time = 0;
    this.rockShapes = new WeakMap();
    this.resize();
    window.addEventListener('resize', () => this.resize());
  }

  resize() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.w = w;
    this.h = h;
    this.canvas.width = Math.floor(w * this.dpr);
    this.canvas.height = Math.floor(h * this.dpr);
    this.canvas.style.width = w + 'px';
    this.canvas.style.height = h + 'px';
    const area = w * h;
    this.zoom = clamp(Math.sqrt(area / (1440 * 810)), 0.68, 1.16);
    this.viewW = w / this.zoom;
    this.viewH = h / this.zoom;
  }

  render(game, dt) {
    const { ctx } = this;
    this.time = game.time;
    this.cam = game.camera;
    this.viewW = this.w / this.zoom;
    this.viewH = this.h / this.zoom;

    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.clearRect(0, 0, this.w, this.h);

    drawBackground(this, game);

    // World-space layer.
    const s = this.dpr * this.zoom;
    ctx.save();
    ctx.setTransform(s, 0, 0, s, this.dpr * (this.w / 2 - this.cam.x * this.zoom), this.dpr * (this.h / 2 - this.cam.y * this.zoom));
    drawSeabed(this, game);
    drawRocks(this, game);
    drawLandmarks(this, game);
    drawDecorations(this, game);
    drawVents(this, game);
    drawSurfaceAndBoat(this, game);
    drawPickups(this, game);
    drawSchools(this, game);
    drawCreatures(this, game);
    drawEffects(this, game);
    drawParticles(this, game);
    drawPlayer(this, game);
    ctx.restore();

    updateSnow(this, dt, game);
    drawSnow(this);
    drawLighting(this, game);
  }

  drawMinimap(game, canvas) {
    drawMinimap(this, game, canvas);
  }
}

import {
  clamp, damp, dist, formatTime, angleTo,
} from './utils.js';
import {
  WORLD, ZONES, ZONE_BY_ID, RESOURCE_META, UPGRADES,
  zoneAtY, yToDepth, upgradeCost,
} from './world.js';
import { Player, Particles, createCreatures, updateCreatures, repelCreatures } from './entities.js';
import { Renderer } from './render/index.js';
import { defaultSave, loadSave, writeSave, clearSave } from './save.js';

const KEY_ACTIONS = new Set(['KeyE', 'KeyQ', 'KeyF', 'KeyU', 'Escape', 'Space']);

export class Game {
  constructor(canvas, audio) {
    this.canvas = canvas;
    this.audio = audio;
    this.renderer = new Renderer(canvas);
    this.save = loadSave() || defaultSave();
    this.player = new Player();
    this.world = null;
    this.creatures = [];
    this.particles = new Particles();
    this.effects = [];
    this.camera = { x: WORLD.baseX, y: 420 };
    this.state = 'menu';
    this.time = 0;
    this.zone = ZONES[0];
    this.input = { x: 0, y: 0, boost: false };
    this.joystick = { x: 0, y: 0 };
    this.mobileBoost = false;
    this.keys = {};
    this.nearestInteract = null;
    this.pulseCooldown = 0;
    this.sonarCooldown = 0;
    this.autosave = 0;
    this.uiTimer = 0;
    this.shake = 0;
    this.pressureWarning = false;
    this.surfaceAir = false;
    this.inVent = false;
    this.lowO2Warned = false;
    this.lowHullWarned = false;
    this.pressureWarned = new Set();
    this.ventBubbleTimer = 0;
    this.deathInfo = null;
    this.ui = null;
    this.sessionStart = 0;
    this.menuTime = 0;
    this.completedToast = false;
    this.init();
  }

  init() {
    this.world = this.world || null;
    // createWorld is deterministic, but import lazily to keep constructor order clear.
    this.world = this.createWorld();
    this.player.applyUpgrades(this.save.upgrades);
    const p = this.save.player || { x: WORLD.baseX, y: 280, oxygen: this.player.maxOxygen, hull: this.player.maxHull };
    this.player.placeAt(
      clamp(p.x || WORLD.baseX, 80, WORLD.width - 80),
      clamp(p.y || 280, 40, WORLD.height - 120),
      p.oxygen || this.player.maxOxygen,
      p.hull || this.player.maxHull,
    );
    this.zone = zoneAtY(this.player.y);
    this.creatures = createCreatures(this.world);
    this.camera.x = clamp(this.player.x, this.renderer.viewW / 2, WORLD.width - this.renderer.viewW / 2);
    this.camera.y = clamp(this.player.y, this.renderer.viewH / 2 - 260, WORLD.height - this.renderer.viewH / 2);
    this.bindInput();
    window.addEventListener('visibilitychange', () => {
      if (document.hidden && this.state === 'playing') this.persist();
    });
    window.addEventListener('beforeunload', () => {
      if (this.save.started) this.persist();
    });
  }

  createWorld() {
    // Imported here via a dynamic require-like static reference keeps the build simple.
    return createWorldCached();
  }

  bindInput() {
    window.addEventListener('keydown', (e) => {
      if (KEY_ACTIONS.has(e.code) || ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault();
      this.keys[e.code] = true;
      if (e.repeat) return;
      if (this.state === 'playing') {
        if (e.code === 'KeyE') this.interact();
        else if (e.code === 'KeyQ' || e.code === 'Space') this.pulse();
        else if (e.code === 'KeyF') this.sonarPing();
        else if (e.code === 'KeyU') this.openUpgrades();
        else if (e.code === 'Escape') this.pause();
      } else if (this.state === 'paused') {
        if (e.code === 'Escape') this.resume();
      } else if (this.state === 'upgrades') {
        if (e.code === 'Escape' || e.code === 'KeyU') this.closeUpgrades();
      }
    });
    window.addEventListener('keyup', (e) => {
      this.keys[e.code] = false;
    });
    window.addEventListener('blur', () => {
      this.keys = {};
      this.mobileBoost = false;
      this.joystick = { x: 0, y: 0 };
    });
  }

  setJoystick(x, y) {
    this.joystick.x = x;
    this.joystick.y = y;
  }

  setMobileBoost(v) {
    this.mobileBoost = !!v;
  }

  showMenu() {
    this.state = 'menu';
    this.menuTime = 0;
    this.nearestInteract = null;
    this.ui.showMenu(this.save);
  }

  startDive(resume = true) {
    this.audio.init();
    this.audio.setMuted(this.save.muted);
    this.player.applyUpgrades(this.save.upgrades);

    if (this.save.started && resume) {
      const p = this.save.player || {};
      const x = clamp(p.x || WORLD.baseX, 80, WORLD.width - 80);
      const y = clamp(p.y || 280, 40, WORLD.height - 120);
      this.player.placeAt(x, y, p.oxygen || this.player.maxOxygen, p.hull || this.player.maxHull);
    } else {
      this.player.placeAt(WORLD.baseX, 280, this.player.maxOxygen, this.player.maxHull);
      this.save.started = true;
      this.save.player = { x: WORLD.baseX, y: 280, oxygen: this.player.maxOxygen, hull: this.player.maxHull };
      this.save.stats.dives = (this.save.stats.dives || 0) + 1;
    }

    if (this.player.hull <= 0 || this.player.oxygen <= 0) {
      this.player.placeAt(WORLD.baseX, 280, this.player.maxOxygen, this.player.maxHull);
    }

    this.zone = zoneAtY(this.player.y);
    if (!this.save.discoveredZones.includes(this.zone.id)) this.save.discoveredZones.push(this.zone.id);
    this.camera.x = this.player.x;
    this.camera.y = this.player.y;
    this.state = 'playing';
    this.sessionStart = performance.now();
    this.lowO2Warned = false;
    this.lowHullWarned = false;
    this.pressureWarned.clear();
    this.nearestInteract = null;
    this.ui.showGame(this);
    this.ui.updateHUD(this, true);
    this.persist();
    this.audio.zone();
    this.ui.toast('Dive commenced. Keep an eye on your oxygen.', { icon: 'info' });
    if (this.save.relics.length >= 3 && !this.save.completed) {
      this.ui.toast('All relic shards aboard. Return to the Aurora at the surface.', { icon: 'relic', tone: 'gold' });
    }
  }

  newExpedition() {
    clearSave();
    this.save = defaultSave();
    this.save.started = true;
    this.save.stats.dives = 1;
    this.player.applyUpgrades(this.save.upgrades);
    this.player.placeAt(WORLD.baseX, 280, this.player.maxOxygen, this.player.maxHull);
    this.creatures = createCreatures(this.world);
    this.particles.items.length = 0;
    this.effects.length = 0;
    this.zone = ZONES[0];
    this.camera.x = this.player.x;
    this.camera.y = this.player.y;
    this.lowO2Warned = false;
    this.lowHullWarned = false;
    this.pressureWarned.clear();
    this.state = 'playing';
    this.ui.showGame(this);
    this.ui.updateHUD(this, true);
    this.persist();
    this.audio.init();
    this.audio.setMuted(this.save.muted);
    this.audio.zone();
    this.ui.toast('New expedition logged. The Aurora is waiting.', { icon: 'info' });
  }

  resume() {
    if (this.state !== 'paused' && this.state !== 'upgrades') return;
    this.state = 'playing';
    this.ui.hideScreens();
    this.ui.updateHUD(this, true);
  }

  pause() {
    if (this.state !== 'playing') return;
    this.state = 'paused';
    this.persist();
    this.ui.openPause(this);
  }

  openUpgrades() {
    if (this.state === 'menu' || this.state === 'dead' || this.state === 'victory') return;
    this.state = 'upgrades';
    this.ui.openUpgrades(this);
  }

  closeUpgrades() {
    if (this.state !== 'upgrades') return;
    this.state = 'playing';
    this.ui.hideScreens();
    this.ui.updateHUD(this, true);
  }

  buyUpgrade(id) {
    const def = UPGRADES.find((u) => u.id === id);
    if (!def) return;
    const lvl = this.save.upgrades[id] || 0;
    if (lvl >= def.max) return;
    const cost = def.cost(lvl);
    if (!cost) return;
    for (const [res, amount] of Object.entries(cost)) {
      if ((this.save.resources[res] || 0) < amount) return;
    }
    for (const [res, amount] of Object.entries(cost)) this.save.resources[res] -= amount;
    this.save.upgrades[id] = lvl + 1;
    this.player.applyUpgrades(this.save.upgrades);
    if (id === 'hull') this.player.hull = Math.min(this.player.maxHull, this.player.hull + 25);
    this.audio.upgrade();
    this.ui.toast(`${def.name} upgraded to Mk.${lvl + 1}.`, { icon: 'upgrade', tone: 'gold' });
    this.ui.refreshUpgrades(this);
    this.ui.updateHUD(this, true);
    this.persist();
  }

  returnToMenu() {
    this.persist();
    this.state = 'menu';
    this.ui.showMenu(this.save);
    this.audio.setMuted(this.save.muted);
  }

  toggleMute() {
    this.save.muted = !this.save.muted;
    this.audio.setMuted(this.save.muted);
    this.ui.setMuted(this.save.muted);
    this.persist();
  }

  getInput() {
    let x = 0;
    let y = 0;
    if (this.keys.KeyA || this.keys.ArrowLeft) x -= 1;
    if (this.keys.KeyD || this.keys.ArrowRight) x += 1;
    if (this.keys.KeyW || this.keys.ArrowUp) y -= 1;
    if (this.keys.KeyS || this.keys.ArrowDown) y += 1;
    if (Math.abs(this.joystick.x) > 0.08 || Math.abs(this.joystick.y) > 0.08) {
      x = this.joystick.x;
      y = this.joystick.y;
    }
    const m = Math.hypot(x, y);
    if (m > 1) {
      x /= m;
      y /= m;
    }
    return {
      x,
      y,
      boost: !!(this.keys.ShiftLeft || this.keys.ShiftRight || this.mobileBoost),
    };
  }

  update(dt) {
    this.time += dt;
    if (this.state === 'menu') {
      this.updateMenu(dt);
      return;
    }
    if (this.state !== 'playing') {
      this.updateEffects(dt);
      this.particles.update(dt);
      this.shake = damp(this.shake, 0, 6, dt);
      return;
    }

    const input = this.getInput();
    this.player.update(dt, input, this.world, this);

    this.updateOxygen(dt, input);
    this.updatePressure(dt);
    this.updateVents(dt);
    this.updateCreatures(dt);
    this.updateSchools(dt);
    this.updatePickups();
    this.updateEffects(dt);
    this.particles.update(dt);
    this.updateCooldowns(dt);
    this.updateCamera(dt);
    this.updateZone();

    this.save.stats.time += dt;
    this.save.stats.maxDepth = Math.max(this.save.stats.maxDepth || 0, yToDepth(this.player.y));

    this.autosave += dt;
    if (this.autosave > 5) {
      this.autosave = 0;
      this.persist();
    }

    this.uiTimer -= dt;
    if (this.uiTimer <= 0) {
      this.uiTimer = 0.075;
      this.ui.updateHUD(this);
    }

    if (this.player.hull <= 0 && this.state === 'playing') this.die();
    this.checkVictory();
  }

  updateMenu(dt) {
    this.menuTime += dt;
    this.time += 0;
    this.camera.x = WORLD.baseX + Math.sin(this.menuTime * 0.055) * 280;
    this.camera.y = 470 + Math.sin(this.menuTime * 0.08) * 130;
    this.particles.update(dt);
    if (Math.random() < dt * 2.2) {
      this.particles.bubble(
        this.camera.x + (Math.random() - 0.5) * 700,
        this.camera.y + (Math.random() - 0.5) * 500,
        { size: Math.random() * 3 + 1, rise: 20 + Math.random() * 50, life: 2 + Math.random() * 3 },
      );
    }
    this.shake = damp(this.shake, 0, 6, dt);
  }

  updateOxygen(dt, input) {
    const p = this.player;
    const zone = this.zone;
    this.surfaceAir = p.y < 120;
    this.inVent = false;
    let ventRefill = false;
    for (const vent of this.world.vents) {
      if (Math.abs(p.x - vent.x) < 108 && p.y > vent.y - 540 && p.y < vent.y + 70) {
        this.inVent = true;
        ventRefill = true;
        break;
      }
    }
    if (this.surfaceAir) {
      p.oxygen = Math.min(p.maxOxygen, p.oxygen + 28 * dt);
    } else if (ventRefill) {
      p.oxygen = Math.min(p.maxOxygen, p.oxygen + 19 * dt);
    } else {
      const depthPenalty = 1 + clamp((p.y - zone.y0) / 9000, 0, 0.25);
      const boostDrain = p.boosting ? 1.65 : 0;
      p.oxygen = Math.max(0, p.oxygen - (zone.drain * depthPenalty + boostDrain) * dt);
    }

    if (p.oxygen <= 0) {
      this.environmentDamage(4.6 * dt, 'oxygen starvation');
      if (!this.lowO2Warned) {
        this.lowO2Warned = true;
        this.ui.toast('Oxygen depleted. Hull is taking damage.', { icon: 'danger', tone: 'danger' });
      }
    } else if (p.oxygen < 24 && !this.lowO2Warned) {
      this.lowO2Warned = true;
      this.ui.toast('Low oxygen. Surface or find a bubble vent.', { icon: 'oxygen', tone: 'danger' });
      this.audio.tone(220, 0.25, 'square', 0.03, 80);
    } else if (p.oxygen > 40) {
      this.lowO2Warned = false;
    }
  }

  updatePressure(dt) {
    const deficit = Math.max(0, this.zone.pressure - this.player.hullLevel);
    if (deficit > 0) {
      this.pressureWarning = true;
      this.environmentDamage(1.75 * deficit * dt, 'pressure');
      if (!this.pressureWarned.has(this.zone.id)) {
        this.pressureWarned.add(this.zone.id);
        this.ui.toast(`Pressure exceeds hull rating in ${this.zone.name}. Upgrade hull plating or ascend.`, { icon: 'danger', tone: 'danger' });
        this.audio.tone(70, 0.7, 'sine', 0.05, -20);
      }
    } else {
      this.pressureWarning = false;
    }
    if (this.player.hull < this.player.maxHull * 0.28 && !this.lowHullWarned) {
      this.lowHullWarned = true;
      this.ui.toast('Hull integrity critical. Find a repair kit or return to the Aurora.', { icon: 'danger', tone: 'danger' });
    }
    if (this.player.hull > this.player.maxHull * 0.45) this.lowHullWarned = false;
  }

  updateVents(dt) {
    this.ventBubbleTimer -= dt;
    if (this.ventBubbleTimer > 0) return;
    this.ventBubbleTimer = 0.2;
    for (const vent of this.world.vents) {
      if (Math.abs(vent.x - this.player.x) > 1800 || Math.abs(vent.y - this.player.y) > 1300) continue;
      this.particles.bubble(
        vent.x + (Math.random() - 0.5) * 60,
        vent.y - Math.random() * 180,
        { size: 2 + Math.random() * 4, rise: 28 + Math.random() * 40, life: 2.5 + Math.random() * 2, alpha: 0.55 },
      );
    }
  }

  updateCreatures(dt) {
    updateCreatures(this.creatures, this.player, dt, this);
  }

  updateSchools(dt) {
    for (const s of this.world.schools) {
      const d = dist(s.x, s.y, this.player.x, this.player.y);
      let speed = s.speed;
      if (d < 250) {
        s.dir = this.player.x < s.x ? 1 : -1;
        speed = s.speed * 2.4;
        s.y += (s.y > this.player.y ? 1 : -1) * 24 * dt;
      }
      s.x += s.dir * speed * dt;
      s.y += Math.sin(this.time * 0.8 + s.phase) * 3 * dt;
      const zone = ZONE_BY_ID[s.zone] || ZONES[0];
      s.y = clamp(s.y, zone.y0 + 90, zone.y1 - 90);
      if (s.x < 100) {
        s.x = 100;
        s.dir = 1;
      } else if (s.x > WORLD.width - 100) {
        s.x = WORLD.width - 100;
        s.dir = -1;
      }
    }
  }

  updatePickups() {
    let best = null;
    let bestD = Infinity;
    const p = this.player;
    const consider = (kind, obj, radius) => {
      const d = dist(p.x, p.y, obj.x, obj.y);
      if (d < radius && d < bestD) {
        bestD = d;
        best = { kind, id: obj.id, x: obj.x, y: obj.y, data: obj };
      }
    };
    for (const node of this.world.nodes) {
      if (this.save.collectedNodes.includes(node.id)) continue;
      consider('node', node, 82);
    }
    for (const chest of this.world.chests) {
      if (this.save.openedChests.includes(chest.id)) continue;
      consider('chest', chest, 106);
    }
    for (const relic of this.world.relics) {
      if (this.save.relics.includes(relic.id)) continue;
      consider('relic', relic, 108);
    }
    if (!this.save.leviathanPearl) consider('pearl', this.world.leviathanPearl, 118);
    this.nearestInteract = best;
    this.ui.updatePrompt(this);
  }

  updateEffects(dt) {
    for (let i = this.effects.length - 1; i >= 0; i--) {
      const e = this.effects[i];
      e.life -= dt;
      if (e.life <= 0) this.effects.splice(i, 1);
    }
    this.shake = damp(this.shake, 0, 6, dt);
  }

  updateCooldowns(dt) {
    this.pulseCooldown = Math.max(0, this.pulseCooldown - dt);
    this.sonarCooldown = Math.max(0, this.sonarCooldown - dt);
  }

  updateCamera(dt) {
    const leadX = clamp(this.player.vx * 0.32, -150, 150);
    const leadY = clamp(this.player.vy * 0.22, -100, 100);
    const halfW = this.renderer.viewW / 2;
    const halfH = this.renderer.viewH / 2;
    const minX = Math.min(halfW, WORLD.width / 2);
    const maxX = Math.max(WORLD.width - halfW, WORLD.width / 2);
    const minY = halfH - 280;
    const maxY = WORLD.height - halfH;
    const tx = clamp(this.player.x + leadX, minX, maxX);
    const ty = clamp(this.player.y + leadY, minY, maxY);
    this.camera.x = damp(this.camera.x, tx, 3.6, dt);
    this.camera.y = damp(this.camera.y, ty, 3.4, dt);
  }

  updateZone() {
    const zone = zoneAtY(this.player.y);
    if (zone.id !== this.zone.id) {
      this.zone = zone;
      const newDiscovery = !this.save.discoveredZones.includes(zone.id);
      if (newDiscovery) {
        this.save.discoveredZones.push(zone.id);
        this.ui.toast(`${zone.name} — ${zone.desc}`, { icon: 'zone', tone: 'gold' });
        this.persist();
      } else {
        this.ui.toast(`Entering ${zone.name}.`, { icon: 'zone' });
      }
      this.audio.zone();
      this.ui.updateHUD(this, true);
    }
  }

  checkVictory() {
    if (this.save.relics.length < 3 || this.save.completed) return;
    if (this.player.y < 170 && dist(this.player.x, this.player.y, WORLD.baseX, 90) < 520) {
      this.save.completed = true;
      this.save.stats.maxDepth = Math.max(this.save.stats.maxDepth, yToDepth(this.player.y));
      this.state = 'victory';
      this.persist();
      this.audio.victory();
      this.ui.showVictory(this);
    }
  }

  interact() {
    if (this.state !== 'playing') return;
    const target = this.nearestInteract;
    if (!target) return;
    if (target.kind === 'node') {
      const node = target.data;
      this.save.collectedNodes.push(node.id);
      if (node.type === 'repair') {
        this.player.hull = Math.min(this.player.maxHull, this.player.hull + 38);
        this.ui.toast('Repair kit installed — hull +38.', { icon: 'repair', tone: 'gold' });
      } else {
        this.addResource(node.type, node.amount);
        this.ui.toast(`+${node.amount} ${RESOURCE_META[node.type].name}`, { icon: node.type });
      }
      this.particles.burst(node.x, node.y, RESOURCE_META[node.type].glow, 14, 120);
      this.effects.push({ type: 'pickup', x: node.x, y: node.y, life: 0.6, maxLife: 0.6, color: RESOURCE_META[node.type].glow });
      this.audio.collect(node.type);
      this.nearestInteract = null;
      this.ui.updateHUD(this, true);
      this.persist();
    } else if (target.kind === 'chest') {
      const chest = target.data;
      this.save.openedChests.push(chest.id);
      const loot = chest.loot;
      for (const [res, amount] of Object.entries(loot)) if (amount > 0) this.addResource(res, amount, true);
      this.save.stats.chests = (this.save.stats.chests || 0) + 1;
      const bits = [];
      if (loot.scrap) bits.push(`${loot.scrap} salvage`);
      if (loot.pearl) bits.push(`${loot.pearl} pearls`);
      if (loot.crystal) bits.push(`${loot.crystal} crystals`);
      this.ui.toast(`${chest.label ? chest.label + ' — ' : ''}supply chest: ${bits.join(', ')}`, { icon: 'chest', tone: 'gold' });
      this.particles.burst(chest.x, chest.y, '#ffd08a', 24, 180);
      this.effects.push({ type: 'pickup', x: chest.x, y: chest.y, life: 0.8, maxLife: 0.8, color: '#ffd08a' });
      this.audio.chest();
      this.nearestInteract = null;
      this.ui.updateHUD(this, true);
      this.persist();
    } else if (target.kind === 'relic') {
      const relic = target.data;
      if (this.save.relics.includes(relic.id)) return;
      this.save.relics.push(relic.id);
      this.particles.burst(relic.x, relic.y, '#ffe2a4', 34, 240);
      this.effects.push({ type: 'pickup', x: relic.x, y: relic.y, life: 1.2, maxLife: 1.2, color: '#ffe2a4' });
      this.audio.relic();
      this.shake = 8;
      const count = this.save.relics.length;
      this.ui.toast(`${relic.name} recovered — ${count} / 3. ${relic.lore}`, { icon: 'relic', tone: 'gold' });
      if (count >= 3) {
        this.ui.toast('All three relic shards are aboard. Return to the Aurora at the surface.', { icon: 'relic', tone: 'gold' });
      }
      this.nearestInteract = null;
      this.ui.updateHUD(this, true);
      this.persist();
    } else if (target.kind === 'pearl') {
      this.save.leviathanPearl = true;
      this.addResource('crystal', 15, true);
      this.addResource('pearl', 10, true);
      this.addResource('scrap', 10, true);
      this.particles.burst(target.x, target.y, '#ffe8b8', 42, 260);
      this.audio.victory();
      this.shake = 10;
      this.ui.toast('The Leviathan Pearl is yours. A legendary find.', { icon: 'relic', tone: 'gold' });
      this.nearestInteract = null;
      this.ui.updateHUD(this, true);
      this.persist();
    }
  }

  addResource(type, amount, silent = false) {
    if (!RESOURCE_META[type] || type === 'repair') return;
    this.save.resources[type] = (this.save.resources[type] || 0) + amount;
    this.save.stats[type] = (this.save.stats[type] || 0) + amount;
    this.save.stats.nodes = (this.save.stats.nodes || 0) + 1;
    if (!silent) this.ui.updateHUD(this, true);
  }

  pulse() {
    if (this.state !== 'playing' || this.pulseCooldown > 0) return;
    const lvl = this.save.upgrades.pulse || 0;
    const radius = 260 + lvl * 45;
    this.pulseCooldown = 9 - lvl * 1.2;
    this.effects.push({ type: 'pulse', x: this.player.x, y: this.player.y, radius, life: 0.85, maxLife: 0.85 });
    repelCreatures(this.creatures, this.player.x, this.player.y, radius, this.player);
    this.particles.burst(this.player.x, this.player.y, '#aefcff', 26, 260);
    this.shake = 6;
    this.audio.pulse();
    this.ui.updateHUD(this, true);
  }

  sonarPing() {
    if (this.state !== 'playing' || this.sonarCooldown > 0) return;
    this.sonarCooldown = 14;
    this.effects.push({ type: 'sonar', x: this.player.x, y: this.player.y, radius: 1900, life: 1.7, maxLife: 1.7 });
    this.audio.sonar();
    let found = null;
    let best = Infinity;
    for (const relic of this.world.relics) {
      if (this.save.relics.includes(relic.id)) continue;
      const d = dist(this.player.x, this.player.y, relic.x, relic.y);
      if (d < 2200 && d < best) {
        best = d;
        found = relic;
      }
    }
    if (found) {
      const dx = found.x - this.player.x;
      const dy = found.y - this.player.y;
      const dir = Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'east' : 'west') : (dy > 0 ? 'below' : 'above');
      this.ui.toast(`Relic signature detected ${dir} — ${Math.round(best / 10)} m.`, { icon: 'sonar', tone: 'gold' });
    } else {
      this.ui.toast('Sonar sweep complete. No relic signature in range.', { icon: 'sonar' });
    }
    this.ui.updateHUD(this, true);
  }

  damage(amount, source) {
    if (this.state !== 'playing' || this.player.invuln > 0) return;
    this.player.hull = Math.max(0, this.player.hull - amount);
    this.player.invuln = 1.15;
    this.player.hitFlash = 0.55;
    this.shake = Math.min(14, 5 + amount * 0.45);
    this.particles.damage(this.player.x, this.player.y);
    this.audio.damage();
    this.ui.flashDamage();
    this.ui.updateHUD(this, true);
    if (this.player.hull <= 0) this.die();
  }

  environmentDamage(amount, source) {
    if (this.state !== 'playing') return;
    this.player.hull = Math.max(0, this.player.hull - amount);
    if (amount > 0.12) this.player.hitFlash = Math.max(this.player.hitFlash, Math.min(0.35, amount * 0.15));
    if (this.player.hull <= 0) this.die();
  }

  die() {
    if (this.state !== 'playing') return;
    this.state = 'dead';
    this.save.stats.deaths = (this.save.stats.deaths || 0) + 1;
    const lost = {};
    for (const key of ['scrap', 'pearl', 'crystal']) {
      const amount = Math.floor((this.save.resources[key] || 0) * 0.2);
      if (amount > 0) {
        lost[key] = amount;
        this.save.resources[key] -= amount;
      }
    }
    this.deathInfo = {
      depth: Math.round(yToDepth(this.player.y)),
      zone: this.zone.name,
      lost,
    };
    this.save.player = { x: WORLD.baseX, y: 280, oxygen: this.player.maxOxygen, hull: this.player.maxHull };
    this.player.hitFlash = 0;
    this.audio.death();
    this.shake = 18;
    this.ui.showDeath(this);
    this.persist();
  }

  respawn() {
    this.player.placeAt(WORLD.baseX, 280, this.player.maxOxygen, this.player.maxHull);
    this.camera.x = this.player.x;
    this.camera.y = this.player.y;
    this.zone = ZONES[0];
    this.state = 'playing';
    this.lowO2Warned = false;
    this.lowHullWarned = false;
    this.pressureWarned.clear();
    this.save.stats.dives = (this.save.stats.dives || 0) + 1;
    this.save.player = { x: WORLD.baseX, y: 280, oxygen: this.player.maxOxygen, hull: this.player.maxHull };
    this.ui.showGame(this);
    this.ui.updateHUD(this, true);
    this.ui.toast('Escape pod recovered. The Aurora patched you up.', { icon: 'repair', tone: 'gold' });
    this.audio.zone();
    this.persist();
  }

  continueAfterVictory() {
    this.state = 'playing';
    this.ui.showGame(this);
    this.ui.updateHUD(this, true);
    this.ui.toast('Free exploration enabled. The deep is still open.', { icon: 'info' });
  }

  persist() {
    if (!this.save.started) return;
    if (this.state !== 'dead') {
      this.save.player = {
        x: this.player.x,
        y: this.player.y,
        oxygen: this.player.oxygen,
        hull: this.player.hull,
      };
    }
    this.save.stats.maxDepth = Math.max(this.save.stats.maxDepth || 0, yToDepth(this.player.y));
    writeSave(this.save);
  }

  getObjective() {
    if (this.save.completed) return 'Expedition complete. Explore freely.';
    if (this.save.relics.length >= 3) return 'Return to the Aurora at the surface to complete the expedition.';
    if (this.save.relics.length === 2) return 'One relic shard remains. Sonar pings can locate the last signature.';
    if (this.save.relics.length === 1) return 'Two relic shards remain. Descend deeper and scan for signatures.';
    return 'Recover the three lost relic shards from the deep zones.';
  }

  getPrompt() {
    const t = this.nearestInteract;
    if (!t) return null;
    if (t.kind === 'node') {
      if (t.data.type === 'repair') return 'Install repair kit';
      return `Collect ${RESOURCE_META[t.data.type].name} ×${t.data.amount}`;
    }
    if (t.kind === 'chest') return t.data.label ? `Open ${t.data.label}` : 'Open supply chest';
    if (t.kind === 'relic') return `Recover ${t.data.name}`;
    if (t.kind === 'pearl') return 'Take the Leviathan Pearl';
    return null;
  }

  render(dt) {
    this.renderer.render(this, dt);
  }
}

